1	/// The Jellyfin dialog on Home: sign in, then pick a movie as this viewer's copy.
2	library;
3	
4	import 'dart:async';
5	
6	import 'package:flutter/material.dart';
7	
8	import 'format.dart';
9	import 'jellyfin.dart';
10	import 'local_copy.dart';
11	import 'theme.dart';
12	import 'widgets/button.dart';
13	import 'widgets/chrome.dart';
14	import 'widgets/field.dart';
15	
16	/// Resolves to the picked movie as a remote copy, or null when closed. With a [session] it opens
17	/// on the movie list; without one, on the sign-in form.
18	Future<LocalCopy?> showJellyfinPicker(
19	  BuildContext context, {
20	  required JellyfinApi api,
21	  required JellyfinSession? session,
22	  required ValueChanged<JellyfinSession> onSession,
23	}) => showDialog<LocalCopy>(
24	  context: context,
25	  barrierColor: const Color(0x8C000000),
26	  builder: (_) =>
27	      JellyfinDialog(api: api, session: session, onSession: onSession),
28	);
29	
30	class JellyfinDialog extends StatefulWidget {
31	  const JellyfinDialog({
32	    super.key,
33	    required this.api,
34	    required this.session,
35	    required this.onSession,
36	  });
37	  final JellyfinApi api;
38	  final JellyfinSession? session;
39	
40	  /// A sign-in succeeded; Home keeps it so the next open goes straight to the list.
41	  final ValueChanged<JellyfinSession> onSession;
42	
