1	/// The viewer's own copy of the video, picked before or inside a room.
2	library;
3	
4	import 'dart:io';
5	
6	import 'package:file_selector/file_selector.dart';
7	import 'package:media_kit/media_kit.dart';
8	
9	import 'format.dart';
10	import 'player.dart';
11	
12	class LocalCopy {
13	  const LocalCopy({
14	    required this.path,
15	    required this.bytes,
16	    required this.itemRef,
17	    this.duration,
18	  }) : title = null,
19	       isRemote = false;
20	
21	  /// A copy streamed from the viewer's Jellyfin: [url] is played as-is and never hashed.
22	  const LocalCopy.remote({
23	    required String url,
24	    required this.itemRef,
25	    required String this.title,
26	    this.duration,
27	  }) : path = url,
28	       bytes = 0,
29	       isRemote = true;
30	
31	  /// The file on disk, or the stream URL of a remote copy.
32	  final String path;
33	  final int bytes;
34	  final String itemRef;
35	  final Duration? duration;
36	  final bool isRemote;
37	
38	  /// Display name of a remote copy; a local one shows its file name.
39	  final String? title;
40	
41	  String get name => title ?? baseName(path);
42	
43	  /// `1.4 GB · 24:10` or `Jellyfin · 0:20`, without the duration when it is unknown.
44	  String get details => [
45	    isRemote ? 'Jellyfin' : fmtBytes(bytes),
46	    if (duration case final d? when d > Duration.zero) fmtTime(d.inMilliseconds),
47	  ].join(' · ');
48	}
49	
50	typedef PickCopy = Future<LocalCopy?> Function();
51	
52	/// Asks for a file, hashes it the same way [SyncPlayer.open] does and probes its duration.
53	Future<LocalCopy?> pickLocalCopy() async {
54	  final file = await openFile();
55	  if (file == null) return null;
56	  final ref = await itemRefForFile(file.path);
57	  final bytes = await File(file.path).length();
58	  return LocalCopy(
59	    path: file.path,
60	    bytes: bytes,
61	    itemRef: ref,
62	    duration: await _probeDuration(file.path),
63	  );
64	}
65	
66	Future<Duration?> _probeDuration(String path) async {
67	  final player = Player();
68	  try {
69	    await player.open(Media(path), play: false);
70	    if (player.state.duration > Duration.zero) return player.state.duration;
71	    return await player.stream.duration
72	        .firstWhere((d) => d > Duration.zero)
73	        .timeout(const Duration(seconds: 4));
74	  } on Object {
75	    return null;
76	  } finally {
77	    await player.dispose();
78	  }
79	}
