25	String? validateServerUrl(String? value) {
26	  final uri = Uri.tryParse((value ?? '').trim());
27	  return uri != null &&
28	          (uri.scheme == 'http' || uri.scheme == 'https') &&
29	          uri.host.isNotEmpty
30	      ? null
31	      : 'Enter an http:// or https:// server URL';
32	}
33	
34	/// Where the pasted invite stands after parsing and `GET /rooms/{id}`.
35	enum InviteState {
36	  empty,
37	  malformed,
38	  checking,
39	  found,
40	  unchecked,
41	  expired,
42	  ended,
43	}
44	
45	class HomeScreen extends StatefulWidget {
46	  const HomeScreen({
47	    super.key,
48	    this.api = const HttpRoomApi(),
49	    this.pickCopy = pickLocalCopy,
50	    this.jellyfin = const HttpJellyfinApi(),
51	    this.initialInvite,
52	    this.forwardedInvites,
53	  });
54	  final RoomApi api;
55	  final PickCopy pickCopy;
56	  final JellyfinApi jellyfin;
57	
58	  /// Invite URL the app was launched with, if any.
59	  final String? initialInvite;
60	
61	  /// Invites that arrived from a second launch while this window was already open.
62	  final Stream<String>? forwardedInvites;
63	
64	  @override
65	  State<HomeScreen> createState() => _HomeScreenState();
66	}
67	
68	class _HomeScreenState extends State<HomeScreen> {
69	  final _invite = TextEditingController();
70	  String _server = defaultServerUrl;
71	  String _name = Platform.localHostname == 'localhost'
72	      ? 'You'
73	      : Platform.localHostname;
74	  int? _rtt;
75	  bool _offline = false;
76	  InviteLink? _link;
77	  InviteState _state = InviteState.empty;
78	  RoomInfo? _info;
79	  int _lookupSeq = 0;
80	  LocalCopy? _copy;
81	  bool _picking = false;
82	  bool _creating = false;
83	  String? _createError;
84	
85	  /// Restored from the saved config at startup, or from a sign-in in the Jellyfin dialog.
86	  JellyfinSession? _jellyfin;
87	
88	  Uri get _serverUri => Uri.parse(_server);
89	
90	  @override
91	  void initState() {
92	    super.initState();
93	    unawaited(_ping());
94	    unawaited(_restoreJellyfin());
95	    final invite = widget.initialInvite;
96	    if (invite != null && invite.isNotEmpty) {
97	      _invite.text = invite;
98	      _onInvite(invite);
99	    }
100	    _forwarded = widget.forwardedInvites?.listen(_takeForwarded);
101	  }
102	
103	  StreamSubscription<String>? _forwarded;
104	
105	  /// A later launch handed us an invite: show it without losing the room we are already in.
106	  void _takeForwarded(String text) {
107	    final link = parseInviteLink(text);
108	    if (link == null || !mounted) return;
109	    _invite.text = text;
110	    _onInvite(text);
111	  }
112	
113	  @override
114	  void dispose() {
115	    unawaited(_forwarded?.cancel());
116	    _invite.dispose();
117	    super.dispose();
118	  }
119	
120	  Future<void> _ping() async {
121	    setState(() {
122	      _rtt = null;
123	      _offline = false;
124	    });
125	    final server = _server;
126	    try {
127	      final rtt = await widget.api.ping(_serverUri);
128	      if (mounted && server == _server) setState(() => _rtt = rtt);
129	    } on Object {
130	      if (mounted && server == _server) setState(() => _offline = true);
131	    }
132	  }
133	
134	  void _onInvite(String text) {
135	    final link = parseInviteLink(text);
136	    final seq = ++_lookupSeq;
137	    setState(() {
138	      _link = link;
139	      _info = null;
140	      _state = text.trim().isEmpty
141	          ? InviteState.empty
142	          : link == null
143	          ? InviteState.malformed
144	          : InviteState.checking;
145	    });
146	    if (link != null) unawaited(_lookup(link, seq));
147	  }
148	
149	  Future<void> _lookup(InviteLink link, int seq) async {
150	    InviteState state;
151	    RoomInfo? info;
152	    try {
153	      info = await widget.api.lookup(_serverUri, link.room);
154	      final exp = tokenExpiryMs(link.token);
155	      state = info == null
156	          ? InviteState.ended
157	          : exp != null && exp <= DateTime.now().millisecondsSinceEpoch
158	          ? InviteState.expired
159	          : InviteState.found;
160	    } on Object {
161	      // Fail open: the code is still shown and joining stays possible.
162	      state = InviteState.unchecked;
163	    }
164	    if (!mounted || seq != _lookupSeq) return;
165	    setState(() {
166	      _state = state;
167	      _info = info;
168	    });
169	  }
170	
171	  Future<void> _paste() async {
172	    final data = await Clipboard.getData(Clipboard.kTextPlain);
173	    final text = data?.text?.trim();
174	    if (text == null || text.isEmpty || !mounted) return;
175	    _invite.text = text;
176	    _onInvite(text);
177	  }
178	
179	  Future<void> _pick() async {
180	    setState(() => _picking = true);
181	    try {
182	      final copy = await widget.pickCopy();
183	      if (copy != null && mounted) setState(() => _copy = copy);
184	    } on Object catch (e) {
185	      if (mounted) {
186	        ScaffoldMessenger.of(
187	          context,
188	        ).showSnackBar(SnackBar(content: Text("Couldn't open that file: $e")));
189	      }
190	    } finally {
191	      if (mounted) setState(() => _picking = false);
192	    }
193	  }
194	
195	  Future<void> _restoreJellyfin() async {
196	    try {
197	      final session = await widget.jellyfin.restore();
198	      if (mounted) _jellyfin ??= session;
199	    } on Object {
200	      // No saved sign-in to offer; the dialog starts at the form.
201	    }
202	  }
203	
204	  Future<void> _pickJellyfin() async {
205	    final copy = await _pickJellyfinCopy();
206	    if (copy != null && mounted) setState(() => _copy = copy);
207	  }
208	
209	  /// Opens the picker without touching Home's own copy — the room screen calls this directly.
210	  Future<LocalCopy?> _pickJellyfinCopy() => showJellyfinPicker(
211	    context,
212	    api: widget.jellyfin,
213	    session: _jellyfin,
214	    onSession: (session) => _jellyfin = session,
215	  );
216	
217	  bool get _linkUsable =>
218	      _link != null &&
219	      (_state == InviteState.found ||
220	          _state == InviteState.unchecked ||
221	          _state == InviteState.checking);
222	
223	  bool get _canJoin =>
224	      _copy != null &&
225	      _link != null &&
226	      (_state == InviteState.found || _state == InviteState.unchecked);
227	
228	  void _join() {
229	    if (!_canJoin) return;
230	    _enter(_link!, copy: _copy);
231	  }
232	
233	  void _enter(InviteLink link, {String? hostId, LocalCopy? copy}) {
234	    Navigator.of(context).push(
235	      wtRoute(
236	        RoomScreen(
237	          server: _serverUri,
238	          room: link.room,
239	          token: link.token,
240	          name: _name,
241	          clientId: hostId,
242	          initialCopy: copy,
243	          pickJellyfin: _pickJellyfinCopy,
244	        ),
245	      ),
246	    );
247	  }
