249	  Future<void> _createRoom() async {
250	    setState(() {
251	      _creating = true;
252	      _createError = null;
253	    });
254	    try {
255	      final created = await widget.api.create(_serverUri);
256	      if (!mounted) return;
257	      setState(() => _creating = false);
258	      final enter = await showRoomReady(
259	        context,
260	        server: _serverUri,
261	        created: created,
262	        name: _name,
