enum _StepState { done, next, todo }

class _Step extends StatelessWidget {
  const _Step({
    required this.n,
    required this.title,
    required this.body,
    required this.state,
    this.last = false,
  });
  final int n;
  final String title;
  final String body;
  final _StepState state;
  final bool last;

  @override
  Widget build(BuildContext context) {
    final next = state == _StepState.next;
    final done = state == _StepState.done;
    final key = Container(
      width: 40,
      height: 48,
      decoration: BoxDecoration(
        color: WtColors.plum2,
        borderRadius: BorderRadius.circular(13),
        border: Border.all(
          color: next ? WtColors.pink : WtColors.line,
          width: 2,
        ),
        boxShadow: next
            ? const [BoxShadow(color: Color(0x40FF5FAE), spreadRadius: 4)]
            : null,
      ),
      child: ClipRRect(
        borderRadius: BorderRadius.circular(11),
        child: Stack(
          children: [
            const Positioned(
              left: 0,
              right: 0,
              top: 0,
              height: 3,
              child: DecoratedBox(
                decoration: BoxDecoration(gradient: WtColors.grad),
              ),
            ),
            Center(
              child: done
                  ? const Icon(
                      Icons.check_rounded,
                      size: 20,
                      color: WtColors.text,
                    )
                  : Text(
                      '$n',
                      style: const TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.w900,
                        color: WtColors.text,
                      ),
                    ),
            ),
          ],
        ),
      ),
    );
    return Opacity(
      opacity: done ? 0.55 : 1,
      child: IntrinsicHeight(
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            SizedBox(
              width: 40,
              child: Column(
                children: [
                  key,
                  if (!last)
                    Expanded(child: Container(width: 2, color: WtColors.line)),
                ],
              ),
            ),
            const SizedBox(width: 14),
            Expanded(
              child: Padding(
                padding: EdgeInsets.only(top: 2, bottom: last ? 0 : 16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Flexible(
                          child: Text(
                            title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              fontSize: 16,
                              fontWeight: FontWeight.w800,
                              color: WtColors.text,
                            ),
                          ),
                        ),
                        if (state != _StepState.todo) ...[
                          const SizedBox(width: 8),
                          Container(
                            padding: const EdgeInsets.fromLTRB(7, 1, 6, 1),
                            decoration: BoxDecoration(
                              color: next
                                  ? const Color(0x29FF5FAE)
                                  : const Color(0x14FFE8F8),
                              borderRadius: BorderRadius.circular(
                                WtRadius.pill,
                              ),
                            ),
                            child: Text(
                              done ? 'DONE' : 'NEXT',
                              style: TextStyle(
                                fontSize: 11,
                                fontWeight: FontWeight.w900,
                                letterSpacing: 0.9,
                                color: next ? WtColors.pink : WtColors.tx3,
                              ),
                            ),
                          ),
                        ],
                      ],
                    ),
                    const SizedBox(height: 2),
                    Text(
                      body,
                      style: const TextStyle(
                        fontSize: 13,
                        height: 1.4,
                        fontWeight: FontWeight.w500,
                        color: WtColors.tx3,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

