286	  Future<void> _apply() async {
287	    if (!_client.clock.ready) return;
288	    await _player.apply(_anchor, _client.clock.serverNow());
289	    if (mounted) setState(() {});
290	  }
291	
292	  Future<void> _poll() async {
293	    if (!_client.clock.ready) return;
294	    await _player.poll(_anchor, _client.clock.serverNow());
295	    if (mounted) setState(() {});
296	  }
