316	  /// A remote copy streams as-is under the ref it was picked with; nothing is hashed.
317	  Future<void> _openRemote(LocalCopy copy) => _open(
318	    () => _player.openSource(uri: copy.path, itemRef: copy.itemRef),
319	    name: copy.name,
320	    source: _sourceOf(copy.itemRef),
321	    durationMs: copy.duration?.inMilliseconds,
