324	  Future<void> _open(
325	    Future<void> Function() open, {
326	    required String name,
327	    required MediaSource source,
328	    int? durationMs,
329	  }) async {
330	    final attempt = (
331	      name: name,
332	      source: source,
333	      open: () => _open(open, name: name, source: source, durationMs: durationMs),
334	    );
335	    setState(() {
336	      _attempt = attempt;
337	      _opening = true;
338	      _openError = null;
339	      _playerError = null;
340	    });
341	    try {
342	      await open();
343	      final ref = _player.itemRef;
344	      if (ref != null) _known[ref] = (name: name, durationMs: durationMs);
345	    } on Object catch (e) {
346	      // Never the raw text: a stream URL carries the viewer's token.
347	      if (mounted) setState(() => _openError = playerErrorReason('$e'));
348	    } finally {
349	      if (mounted) setState(() => _opening = false);
350	    }
351	    await _apply();
352	  }
353	
354	  /// Why our copy can't play, for the error card. A player error only counts while nothing
355	  /// has loaded: decoders also log recoverable errors mid-file.
356	  String? get _error {
357	    if (_openError case final e?) return e;
358	    final logged = _playerError;
359	    if (logged == null || _player.itemRef == null) return null;
360	    return _player.player.state.duration == Duration.zero
361	        ? playerErrorReason(logged)
362	        : null;
363	  }
364	
365	  /// Same path as a local file once the picker hands back a remote copy.
366	  Future<void> _openJellyfin() async {
367	    final pick = widget.pickJellyfin;
368	    if (pick == null) return;
369	    final copy = await pick();
370	    if (copy == null || !mounted) return;
371	    await _openRemote(copy);
372	  }
373	
374	  Future<void> _addToQueue(PickCopy pick) => queuePicked(
375	    pick,
376	    known: _known,
377	    send: (op, args) {
378	      if (mounted) _client.sendIntent(op, args);
379	    },
380	  );
381	
382	  void _play() {
383	    final ref = _player.itemRef;
384	    _client.sendIntent('play', {'item_ref': ?ref});
385	  }
386	
387	  void _pauseRoom() {
388	    _pauseSentAt = DateTime.now();
389	    _client.sendIntent('pause');
390	  }
391	
392	  int get _roomPositionMs {
393	    final anchor = _anchor;
394	    return anchor == null
395	        ? _player.positionMs
396	        : positionAt(anchor, _client.clock.serverNow());
397	  }
398	
399	  void _seekBy(int deltaMs) => _seekTo(_roomPositionMs + deltaMs);
400	
401	  void _seekTo(int ms) =>
402	      _client.sendIntent('seek', {'position_ms': math.max(0, ms)});
403	
404	  /// The room's item again from the start, for everyone.
405	  void _replay() {
406	    final ref = _anchor?.itemRef ?? _player.itemRef;
407	    _client.sendIntent('play', {'item_ref': ?ref, 'position_ms': 0});
408	  }
409	
410	  /// The head of the queue becomes the room's item.
411	  void _playNext() => _client.sendIntent('skip');
412	
413	  void _toggleMute() {
414	    setState(() => _muted = !_muted);
415	    _player.player.setVolume(_muted ? 0 : _volume);
416	  }
417	
418	  void _setVolume(double level) {
419	    setState(() {
420	      _volume = _sessionVolume = level;
421	      _muted = false;
422	    });
423	    _player.player.setVolume(level);
424	  }
425	
426	  void _setAudioTrack(String id) {
427	    for (final t in _player.player.state.tracks.audio) {
428	      if (t.id == id) _player.player.setAudioTrack(t);
429	    }
430	  }
431	
432	  void _setSubtitleTrack(String id) {
433	    for (final t in _player.player.state.tracks.subtitle) {
434	      if (t.id == id) _player.player.setSubtitleTrack(t);
435	    }
436	  }
437	
438	  /// Audio tracks as the player lists them, minus its `auto` and `no` pseudo-tracks.
439	  List<TrackOption> get _audioTracks {
440	    final state = _player.player.state;
441	    return [
442	      for (final t in state.tracks.audio)
443	        if (t.id != 'auto' && t.id != 'no')
444	          (
445	            id: t.id,
446	            label: _trackLabel(t.id, t.title, t.language),
447	            active: t.id == state.track.audio.id,
448	          ),
449	    ];
450	  }
451	
452	  /// `Off` first, then the file's subtitles; empty when it has none.
453	  List<TrackOption> get _subtitleTracks {
454	    final state = _player.player.state;
455	    final active = state.track.subtitle.id;
456	    final real = [
457	      for (final t in state.tracks.subtitle)
458	        if (t.id != 'auto' && t.id != 'no')
459	          (
460	            id: t.id,
461	            label: _trackLabel(t.id, t.title, t.language),
462	            active: t.id == active,
463	          ),
464	    ];
465	    if (real.isEmpty) return const [];
466	    return [(id: 'no', label: 'Off', active: active == 'no'), ...real];
467	  }
468	
469	  static String _trackLabel(String id, String? title, String? language) {
470	    final parts = [
471	      if (title != null && title.trim().isNotEmpty) title.trim(),
472	      if (language != null && language.trim().isNotEmpty)
473	        language.trim().toUpperCase(),
474	    ];
475	    return parts.isEmpty ? 'Track $id' : parts.join(' · ');
476	  }
477	
478	  Future<void> _toggleFullscreen() async {
479	    final next = !_fullscreen;
480	    setState(() => _fullscreen = next);
481	    await (next ? defaultEnterNativeFullscreen() : defaultExitNativeFullscreen());
482	  }
483	
484	  void _showSettings() {
485	    final drift = _player.driftMs;
486	    showDialog<void>(
487	      context: context,
488	      barrierColor: const Color(0x8C000000),
489	      builder: (context) => _SettingsDialog(
490	        rows: [
491	          ('Server', widget.server.host),
492	          ('Room', widget.room),
493	          (
494	            'Connection',
495	            _joined
496	                ? 'Connected · ${_client.clock.rttMs.round()} ms'
497	                : (_gaveUp ?? 'Reconnecting…'),
498	          ),
499	          ('Drift', drift == null ? '—' : '${drift.round()} ms'),
500	          ('Player', _player.status),
501	        ],
502	      ),
503	    );
504	  }
505	
506	  StageMode get _stage {
507	    final anchor = _anchor;
508	    final mine = _player.itemRef;
509	    if (anchor != null && anchor.itemRef != mine) return StageMode.waiting;
510	    return mine == null ? StageMode.empty : StageMode.video;
511	  }
512	
513	  PersonState get _selfState {
514	    final drift = _player.driftMs;
515	    if (!_joined) return PersonState.reconnecting;
516	    if (_player.itemRef == null || _stage == StageMode.waiting) {
517	      return PersonState.noFile;
518	    }
519	    if (_player.player.state.buffering) return PersonState.buffering;
520	    if (drift != null && drift.abs() >= seekAtMs) return PersonState.drifting;
521	    return PersonState.synced;
522	  }
523	
524	  /// Presence plus ourselves. Peers report drift only to the server, so they read as synced.
525	  List<RoomPerson> get _people {
526	    final me = _client.clientId;
527	    final host = _meta?.hostId;
528	    final people = [
529	      for (final m in _members)
530	        m.userId == me
531	            ? RoomPerson(
532	                id: me,
533	                name: widget.name,
534	                you: true,
535	                host: host == me,
536	                state: _selfState,
537	                driftMs: _player.driftMs ?? 0,
538	              )
539	            : RoomPerson(
540	                id: m.userId,
541	                name: m.name ?? 'Guest',
542	                host: host == m.userId,
543	              ),
544	    ];
545	    if (!people.any((p) => p.you)) {
546	      people.insert(
547	        0,
548	        RoomPerson(
549	          id: me,
550	          name: widget.name,
551	          you: true,
552	          host: host == me,
553	          state: _selfState,
554	          driftMs: _player.driftMs ?? 0,
555	        ),
556	      );
557	    }
558	    return [...people.where((p) => p.host), ...people.where((p) => !p.host)];
559	  }
560	
561	  QueueRow _row(String ref, {String? title, int? durationMs}) {
562	    final known = _known[ref];
563	    final parts = ref.split(':');
564	    final duration =
565	        durationMs ??
566	        known?.durationMs ??
567	        (ref == _player.itemRef
568	            ? _player.player.state.duration.inMilliseconds
569	            : null);
570	    final bytes = parts.length > 2 ? int.tryParse(parts[2]) : null;
571	    return (
572	      title:
573	          title ??
574	          known?.name ??
575	          'File ${parts.length > 3 ? parts[3].substring(0, 6) : ref}',
576	      detail: duration != null && duration > 0
577	          ? fmtTime(duration)
578	          : (bytes == null ? '' : fmtBytes(bytes)),
579	      source: _sourceOf(ref),
580	    );
581	  }
582	
583	  String get _title {
584	    final meta = _meta;
585	    if (meta == null) return 'Room';
586	    return meta.hostId == _client.clientId
587	        ? 'Your room'
588	        : "${meta.hostName}'s room";
589	  }
590	
591	  /// Who the room waits on to press play. Anchors carry no author, so this is the pause notice's
592	  /// guess while paused, and the host while nothing has played.
593	  String? get _waitingFor {
594	    final anchor = _anchor;
595	    if (anchor != null) return anchor.paused ? _pause?.by : null;
596	    final meta = _meta;
597	    if (meta == null) return null;
598	    return meta.hostId == _client.clientId ? 'You' : meta.hostName;
599	  }
600	
601	  /// Adjusting while the drift policy nudges or is about to correct a playing copy.
602	  SyncState? get _sync {
603	    final anchor = _anchor;
604	    if (_stage != StageMode.video || anchor == null) return null;
605	    if (anchor.paused) return SyncState.inSync;
606	    return _player.nudging || _player.correction != Correction.none
607	        ? SyncState.adjusting
608	        : SyncState.inSync;
609	  }
610	
611	  RoomViewData get _data {
612	    final state = _player.player.state;
613	    final anchor = _anchor;
614	    final error = _error;
615	    final mine = _player.itemRef;
616	    return RoomViewData(
617	      room: widget.room,
618	      title: _title,
619	      invite: inviteUrl(widget.server, widget.token),
620	      connected: _joined,
621	      connecting: !_joinedOnce,
622	      disconnectReason: _gaveUp,
623	      people: _people,
624	      nowPlaying: anchor == null ? null : _row(anchor.itemRef),
625	      upNext: [
626	        for (final q in _queue)
627	          _row(q.itemRef, title: q.title, durationMs: q.durationMs),
628	      ],
629	      stage: _stage,
630	      mismatch: mine != null,
631	      opening: _opening,
632	      buffering: mine != null && state.buffering,
633	      error: error,
634	      ended: mine != null && state.completed,
635	      waitingFor: _waitingFor,
636	      // Never the remote URL itself: it carries the viewer's token.
637	      fileName: error != null || _opening
638	          ? _attempt?.name
639	          : _known[mine]?.name,
640	      source: error != null || _opening
641	          ? _attempt?.source
642	          : (mine == null ? null : _sourceOf(mine)),
643	      roomSource: anchor == null ? null : _sourceOf(anchor.itemRef),
644	      positionMs: mine == null ? 0 : _roomPositionMs,
645	      durationMs: state.duration.inMilliseconds,
646	      bufferedMs: state.buffer.inMilliseconds,
647	      playing: anchor != null && !anchor.paused,
648	      aspect: (state.width ?? 0) > 0 && (state.height ?? 0) > 0
649	          ? state.width! / state.height!
650	          : 16 / 9,
651	      muted: _muted,
652	      volume: _volume,
653	      rate: anchor?.rate ?? 1,
654	      sync: _sync,
655	      driftMs: _player.driftMs,
656	      audioTracks: _audioTracks,
657	      subtitleTracks: _subtitleTracks,
658	      fullscreen: _fullscreen,
659	      pause: _pause,
660	    );
661	  }
662	
663	  @override
664	  Widget build(BuildContext context) => WtScaffold(
665	    child: RoomView(
666	      data: _data,
667	      video: Video(
668	        controller: _player.video,
669	        controls: NoVideoControls,
670	        fill: _fullscreen ? Colors.black : WtColors.board,
671	        pauseUponEnteringBackgroundMode: false,
672	      ),
673	      onBack: () => Navigator.of(context).pop(),
674	      onOpenFile: _openFile,
675	      onOpenJellyfin: widget.pickJellyfin == null ? null : _openJellyfin,
676	      onPlay: _play,
677	      onPause: _pauseRoom,
678	      onSeekBy: _seekBy,
679	      onSeekTo: _seekTo,
680	      onToggleMute: _toggleMute,
681	      onVolume: _setVolume,
682	      onFullscreen: _toggleFullscreen,
683	      onSettings: _showSettings,
684	      onAddToQueue: () => _addToQueue(widget.pickCopy),
685	      onQueueJellyfin: switch (widget.pickJellyfin) {
686	        final pick? => () => _addToQueue(pick),
687	        null => null,
688	      },
689	      onRetry: _attempt?.open,
690	      onReplay: _replay,
691	      onPlayNext: _playNext,
692	      onAudioTrack: _setAudioTrack,
693	      onSubtitleTrack: _setSubtitleTrack,
694	    ),
695	  );
696	}
697	
