content.content:
1	/// The Room screen's presentation: top bar, stage, rail, dock, toast. Fed a [RoomViewData]
2	/// snapshot and callbacks, so it renders without a socket or a native player.
3	library;
4	
5	import 'dart:async';
6	import 'dart:math' as math;
7	
8	import 'package:flutter/material.dart';
9	import 'package:flutter/services.dart';
10	
11	import 'format.dart';
12	import 'player.dart' show seekAtMs;
13	import 'room_controls.dart';
14	import 'theme.dart';
15	import 'widgets/button.dart';
16	import 'widgets/chrome.dart';
17	import 'widgets/identity.dart';
18	
19	/// Stage shape for scope files; everything else gets a 16:9 stage.
20	const double scopeAspect = 2.39;
21	
22	/// 16:9, or 2.39:1 when the file is scope-wide; the picture letterboxes inside, never stretched.
23	double stageAspect(double fileAspect) =>
24	    fileAspect >= (16 / 9 + scopeAspect) / 2 ? scopeAspect : 16 / 9;
25	
26	/// The video stage box, for layout tests.
27	const Key roomStageKey = ValueKey('room-stage');
28	
29	/// The dock, for the fullscreen auto-hide tests.
30	const Key roomDockKey = ValueKey('room-dock');
31	
32	/// Fullscreen chrome (dock, room cluster, cursor) hides after this long without pointer movement
33	/// or a key, playing or paused. The corner pills never hide.
34	const Duration chromeHideAfter = Duration(milliseconds: 2500);
35	
36	/// How long the "Esc to exit · F toggles" hint stays up after entering fullscreen.
37	const Duration fullscreenHintFor = Duration(seconds: 2);
38	
39	/// Fullscreen glass: the room cluster, the hint and the corner pills sit on this, never on a bar.
40	const BoxDecoration _glass = BoxDecoration(
41	  color: Color(0x99140A20),
42	  borderRadius: BorderRadius.all(Radius.circular(WtRadius.pill)),
43	  border: Border.fromBorderSide(BorderSide(color: WtColors.line, width: 1.5)),
44	);
45	
46	enum PersonState { synced, buffering, drifting, noFile, reconnecting }
47	
48	class RoomPerson {
49	  const RoomPerson({
50	    required this.id,
51	    required this.name,
52	    this.you = false,
53	    this.host = false,
54	    this.state = PersonState.synced,
55	    this.driftMs = 0,
56	  });
57	  final String id;
58	  final String name;
59	  final bool you;
60	  final bool host;
61	  final PersonState state;
62	  final double driftMs;
63	
64	  /// Synced, or drifting within the seek threshold (the player is still nudging it in).
65	  bool get ready => switch (state) {
66	    PersonState.synced => true,
67	    PersonState.drifting => driftMs.abs() < seekAtMs,
68	    PersonState.buffering ||
69	    PersonState.noFile ||
70	    PersonState.reconnecting => false,
71	  };
72	
73	  String get status => switch (state) {
74	    PersonState.synced => 'Synced',
75	    PersonState.buffering => 'Buffering',
76	    PersonState.drifting =>
77	      'Drifting ${driftMs < 0 ? '−' : '+'}${(driftMs.abs() / 1000).round()}s',
78	    PersonState.noFile => 'No file',
79	    PersonState.reconnecting => 'Reconnecting',
80	  };
81	}
82	
83	/// The ready pill's tooltip: who is not ready, and why.
84	String readyDetail(List<RoomPerson> people) {
85	  final waiting = people.where((p) => !p.ready).toList();
86	  if (waiting.isEmpty) return 'Everyone has the file and is in sync.';
87	  return [
88	    'Not ready yet',
89	    for (final p in waiting) '${p.name}${p.you ? ' (you)' : ''} · ${p.status}',
90	  ].join('\n');
91	}
92	
93	enum StageMode { empty, waiting, video }
94	
95	/// Where a copy comes from: a file on disk, or a stream from the viewer's Jellyfin.
96	enum MediaSource { local, jellyfin }
97	
98	/// `In sync`, or `Adjusting` while the drift policy is correcting.
99	enum SyncState { inSync, adjusting }
100	
101	/// [source] is read off the item's ref, so it always matches what will open.
102	typedef QueueRow = ({String title, String detail, MediaSource source});
103	
104	/// Shown as a toast, then named on the stage while playback stays paused.
105	class PauseNotice {
106	  const PauseNotice({required this.serial, required this.positionMs, this.by});
107	  final int serial;
108	  final int positionMs;
109	
110	  /// Who paused, when known (`You`, or the only other person).
111	  final String? by;
112	}
113	
114	class RoomViewData {
115	  const RoomViewData({
116	    required this.room,
117	    this.title = 'Room',
118	    this.invite,
119	    this.connected = true,
120	    this.connecting = false,
121	    this.disconnectReason,
122	    this.people = const [],
123	    this.nowPlaying,
124	    this.upNext = const [],
125	    this.stage = StageMode.empty,
126	    this.mismatch = false,
127	    this.opening = false,
128	    this.buffering = false,
129	    this.error,
130	    this.ended = false,
131	    this.waitingFor,
132	    this.fileName,
133	    this.source,
134	    this.roomSource,
135	    this.positionMs = 0,
136	    this.durationMs = 0,
137	    this.bufferedMs = 0,
138	    this.playing = false,
139	    this.aspect = 16 / 9,
140	    this.muted = false,
141	    this.volume = 100,
142	    this.rate = 1,
143	    this.sync,
144	    this.driftMs,
145	    this.audioTracks = const [],
146	    this.subtitleTracks = const [],
147	    this.fullscreen = false,
148	    this.pause,
149	  });
150	  final String room;
151	  final String title;
152	  final String? invite;
153	  final bool connected;
154	
155	  /// Not connected yet for the first time, as opposed to dropped.
156	  final bool connecting;
157	
158	  /// Set when the connection is gone for good (bad token, room ended); otherwise we retry.
159	  final String? disconnectReason;
160	  final List<RoomPerson> people;
161	
162	  /// The room's item; null while nobody has pressed play.
163	  final QueueRow? nowPlaying;
164	  final List<QueueRow> upNext;
165	  final StageMode stage;
166	
167	  /// In [StageMode.waiting]: a file is open but it is not the room's file.
168	  final bool mismatch;
169	
170	  /// Our copy is being hashed or loaded; [fileName] names it.
171	  final bool opening;
172	
173	  /// The player is waiting for data.
174	  final bool buffering;
175	
176	  /// Why our copy failed to open or play, in words for the error card.
177	  final String? error;
178	
179	  /// Our copy reached its end.
180	  final bool ended;
181	
182	  /// Who the room waits on to press play: a name, `You`, or null when nobody can tell.
183	  final String? waitingFor;
184	
185	  /// Our copy's display name (a Jellyfin copy's picked title, never its URL).
186	  final String? fileName;
187	
188	  /// Where our copy comes from; null without one.
189	  final MediaSource? source;
190	
191	  /// Where the room's item comes from, for the right "open that file" action.
192	  final MediaSource? roomSource;
193	  final int positionMs;
194	  final int durationMs;
195	  final int bufferedMs;
196	  final bool playing;
197	  final double aspect;
198	  final bool muted;
199	
200	  /// 0–100, kept while muted.
201	  final double volume;
