389	class _WtDotState extends State<WtDot> with SingleTickerProviderStateMixin {
390	  late final AnimationController _pulse = AnimationController(
391	    vsync: this,
392	    duration: const Duration(seconds: 2),
393	  );
394	  bool _started = false;
395	
396	  @override
397	  void didChangeDependencies() {
398	    super.didChangeDependencies();
399	    if (!_started &&
400	        widget.style == WtDotStyle.pulse &&
401	        !MediaQuery.of(context).disableAnimations) {
402	      _started = true;
403	      _pulse.repeat(count: 3);
404	    }
405	  }
406	
407	  @override
408	  void dispose() {
409	    _pulse.dispose();
410	    super.dispose();
411	  }
412	
413	  @override
414	  Widget build(BuildContext context) {
415	    final ring = widget.style == WtDotStyle.ring;
416	    return AnimatedBuilder(
417	      animation: _pulse,
418	      builder: (context, _) {
419	        final t = _pulse.isAnimating
420	            ? (_pulse.value / 0.8).clamp(0.0, 1.0)
421	            : 1.0;
422	        return Container(
423	          width: 8,
424	          height: 8,
425	          decoration: BoxDecoration(
426	            shape: BoxShape.circle,
427	            color: ring ? null : widget.color,
428	            border: ring ? Border.all(color: widget.color, width: 2) : null,
429	            boxShadow: t < 1
430	                ? [
431	                    BoxShadow(
432	                      color: widget.color.withValues(alpha: 0.6 * (1 - t)),
433	                      spreadRadius: 7 * t,
434	                    ),
435	                  ]
