262	
263	  testWidgets('rail shows every person state, HOST tag and queue', (
264	    tester,
265	  ) async {
266	    useWindow(tester, desktopSizes.first);
267	    await pumpRoom(tester, video());
268	    expect(find.text('Synced'), findsOneWidget);
269	    expect(find.text('Drifting +2s'), findsOneWidget);
270	    expect(find.text('No file'), findsOneWidget);
271	    expect(find.text('Buffering'), findsOneWidget);
272	    expect(find.text('Reconnecting'), findsOneWidget);
273	    expect(find.text('HOST'), findsOneWidget);
274	    expect(find.text(' (you)'), findsOneWidget);
275	    expect(find.text('Now playing · 1:52:10'), findsOneWidget);
276	    expect(find.text('UP NEXT'), findsOneWidget);
277	    expect(find.text('Nothing queued'), findsNothing);
278	    expect(find.text('12:04 / 1:52:10'), findsOneWidget);
279	  });
280	
281	  group('queue Add', () {
282	    const jellyRef = 'jellyfin:jelly.example/$jellyItemId';
283	    const jellyCopy = LocalCopy.remote(
