import 'package:flutter/gestures.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:watch_together/format.dart';
import 'package:watch_together/local_copy.dart';
import 'package:watch_together/room_controls.dart';
import 'package:watch_together/room_screen.dart' show queuePicked;
import 'package:watch_together/room_view.dart';
import 'package:watch_together/theme.dart';
import 'package:watch_together/widgets/button.dart';

import 'support.dart';

const List<RoomPerson> crowd = [
  RoomPerson(id: 'mika', name: 'Mika', host: true),
  RoomPerson(
    id: 'me',
    name: 'Sam',
    you: true,
    state: PersonState.drifting,
    driftMs: 2300,
  ),
  RoomPerson(id: 'jo', name: 'Jo', state: PersonState.noFile),
  RoomPerson(id: 'al', name: 'Al', state: PersonState.buffering),
  RoomPerson(id: 'ri', name: 'Ri', state: PersonState.reconnecting),
];

RoomViewData video({
  bool connected = true,
  bool playing = true,
  List<RoomPerson> people = crowd,
  PauseNotice? pause,
  String? waitingFor,
  bool fullscreen = false,
  double aspect = 16 / 9,
}) => RoomViewData(
  room: roomCode,
  title: "Mika's room",
  invite: 'https://example.com/join/abc.sig',
  connected: connected,
  people: people,
  nowPlaying: (
    title: 'movie-night_1080p.mkv',
    detail: '1:52:10',
    source: MediaSource.local,
  ),
  upNext: const [
    (
      title: 'episode-02_1080p.mkv',
      detail: '24:10',
      source: MediaSource.jellyfin,
    ),
  ],
  stage: StageMode.video,
  fileName: 'movie-night_1080p.mkv',
  positionMs: 724000,
  durationMs: 6730000,
  bufferedMs: 900000,
  playing: playing,
  pause: pause,
  waitingFor: waitingFor,
  fullscreen: fullscreen,
  aspect: aspect,
);

const RoomViewData empty = RoomViewData(
  room: roomCode,
  people: [
    RoomPerson(
      id: 'me',
      name: 'Sam',
      you: true,
      host: true,
      state: PersonState.noFile,
    ),
  ],
);

void main() {
  setUp(FakeClipboard().install);

  Future<void> pumpRoom(
    WidgetTester tester,
    RoomViewData data, {
    VoidCallback? onPlay,
    VoidCallback? onPause,
    ValueChanged<int>? onSeekBy,
    ValueChanged<int>? onSeekTo,
    VoidCallback? onFullscreen,
    VoidCallback? onToggleMute,
    VoidCallback? onOpenJellyfin,
    VoidCallback? onAddToQueue,
    VoidCallback? onQueueJellyfin,
  }) async {
    await tester.pumpWidget(
      MaterialApp(
        theme: wtTheme(),
        home: WtScaffold(
          child: RoomView(
            data: data,
            video: const ColoredBox(color: Colors.black),
            onBack: () {},
            onOpenFile: () {},
            onOpenJellyfin: onOpenJellyfin,
            onPlay: onPlay ?? () {},
            onPause: onPause ?? () {},
            onSeekBy: onSeekBy ?? (_) {},
            onSeekTo: onSeekTo ?? (_) {},
            onToggleMute: onToggleMute ?? () {},
            onFullscreen: onFullscreen ?? () {},
            onSettings: () {},
            onAddToQueue: onAddToQueue ?? () {},
            onQueueJellyfin: onQueueJellyfin,
          ),
        ),
      ),
    );
    await tester.pump();
  }

  /// Dock tooltips carry their disabled reason (`Back 10 seconds · open a file first`), so match on
  /// the prefix rather than the whole string.
  WtTap tapFor(WidgetTester tester, String tooltip) => tester.widget<WtTap>(
    find
        .ancestor(
          of: find.byWidgetPredicate(
            (w) => w is Tooltip && (w.message ?? '').startsWith(tooltip),
          ),
          matching: find.byType(WtTap),
        )
        .first,
  );

  group('ready pill', () {
    test('label counts ready people, then says all in sync', () {
      expect(readyPillLabel(2, 3), '2 of 3 ready');
      expect(readyPillLabel(3, 3), 'All 3 in sync');
      expect(readyPillLabel(0, 1), '0 of 1 ready');
    });

    testWidgets('yellow N of M ready until everyone is synced', (tester) async {
      useWindow(tester, desktopSizes.first);
      await pumpRoom(tester, video());
      expect(find.text('1 of 5 ready'), findsOneWidget);
    });

    testWidgets('turns into All M in sync', (tester) async {
      useWindow(tester, desktopSizes.first);
      await pumpRoom(
        tester,
        video(
          people: const [
            RoomPerson(id: 'mika', name: 'Mika', host: true),
            RoomPerson(id: 'me', name: 'Sam', you: true),
            RoomPerson(id: 'jo', name: 'Jo'),
          ],
        ),
      );
      expect(find.text('All 3 in sync'), findsOneWidget);
      expect(find.textContaining('ready'), findsNothing);
    });

    testWidgets('default people are ready; one without a file is not', (
      tester,
    ) async {
      useWindow(tester, desktopSizes.first);
      const fresh = [
        RoomPerson(id: 'mika', name: 'Mika', host: true),
        RoomPerson(id: 'me', name: 'Sam', you: true),
        RoomPerson(id: 'jo', name: 'Jo'),
        RoomPerson(id: 'al', name: 'Al'),
      ];
      await pumpRoom(tester, video(people: fresh));
      expect(find.text('All 4 in sync'), findsOneWidget);

      await pumpRoom(
        tester,
        video(
          people: [
            ...fresh.take(3),
            const RoomPerson(id: 'al', name: 'Al', state: PersonState.noFile),
          ],
        ),
      );
      expect(find.text('3 of 4 ready'), findsOneWidget);
    });

    test('only drift beyond the seek threshold counts as not ready', () {
      RoomPerson drifting(double ms) => RoomPerson(
        id: 'x',
        name: 'X',
        state: PersonState.drifting,
        driftMs: ms,
      );
      expect(const RoomPerson(id: 'x', name: 'X').ready, isTrue);
      expect(drifting(-1200).ready, isTrue);
      expect(drifting(2300).ready, isFalse);
      for (final state in [
        PersonState.noFile,
        PersonState.buffering,
        PersonState.reconnecting,
      ]) {
        expect(RoomPerson(id: 'x', name: 'X', state: state).ready, isFalse);
      }
    });
  });

  group('stage', () {
    for (final size in [...desktopSizes, tiledSize]) {
      final label = '${size.width.toInt()}x${size.height.toInt()}';
      for (final (name, fileAspect, want) in [
        ('16:9 file', 16 / 9, 16 / 9),
        ('1.63:1 file', 1.63, 16 / 9),
        ('scope file', 2.39, 2.39),
      ]) {
        testWidgets('is ${want.toStringAsFixed(2)}:1 for a $name at $label', (
          tester,
        ) async {
          useWindow(tester, size);
          await pumpRoom(
            tester,
            RoomViewData(
              room: roomCode,
              people: crowd,
              stage: StageMode.video,
              aspect: fileAspect,
            ),
          );
          final stage = tester.getRect(find.byKey(roomStageKey));
          expect(stage.width / stage.height, closeTo(want, 0.01));
          // Centred in the space left of the rail (the rail is a sheet when tiled).
          final left = size.width - (size.width < 1024 ? 0 : 320);
          expect(stage.center.dx, closeTo(left / 2, 0.5));
        });
      }
    }

    testWidgets('empty stage is 16:9 too', (tester) async {
      useWindow(tester, desktopSizes.first);
      await pumpRoom(tester, empty);
      final stage = tester.getSize(find.byKey(roomStageKey));
      expect(stage.width / stage.height, closeTo(16 / 9, 0.01));
    });
  });

  testWidgets('tiled: the rail becomes a sheet behind the people button', (
    tester,
  ) async {
    useWindow(tester, tiledSize);
    await pumpRoom(tester, video());
    expect(find.text('IN THIS ROOM'), findsNothing);
    await tester.tap(find.byTooltip('People and queue'));
    await tester.pump();
    expect(find.text('IN THIS ROOM'), findsOneWidget);
    expect(find.text('Drifting +2s'), findsOneWidget);
    expect(tester.takeException(), isNull);
    await tester.sendKeyEvent(LogicalKeyboardKey.escape);
    await tester.pump();
    expect(find.text('IN THIS ROOM'), findsNothing);
  });

  testWidgets('rail shows every person state, HOST tag and queue', (
    tester,
  ) async {
    useWindow(tester, desktopSizes.first);
    await pumpRoom(tester, video());
    expect(find.text('Synced'), findsOneWidget);
    expect(find.text('Drifting +2s'), findsOneWidget);
    expect(find.text('No file'), findsOneWidget);
    expect(find.text('Buffering'), findsOneWidget);
    expect(find.text('Reconnecting'), findsOneWidget);
    expect(find.text('HOST'), findsOneWidget);
    expect(find.text(' (you)'), findsOneWidget);
    expect(find.text('Now playing · 1:52:10'), findsOneWidget);
    expect(find.text('UP NEXT'), findsOneWidget);
    expect(find.text('Nothing queued'), findsNothing);
    expect(find.text('12:04 / 1:52:10'), findsOneWidget);
  });

  group('queue Add', () {
    const jellyRef = 'jellyfin:jelly.example/$jellyItemId';
    const jellyCopy = LocalCopy.remote(
      url: 'http://jelly.example/Videos/$jellyItemId/stream?api_key=secret',
      itemRef: jellyRef,
      title: 'sample-room',
      duration: Duration(seconds: 20),
    );

    testWidgets('offers this computer and Jellyfin when a picker exists', (
      tester,
    ) async {
      useWindow(tester, desktopSizes.first);
      var files = 0;
      var jellyfin = 0;
      await pumpRoom(
        tester,
        video(),
        onAddToQueue: () => files++,
        onQueueJellyfin: () => jellyfin++,
      );
      expect(find.text('From this computer'), findsNothing);
      await tester.tap(find.text('Add'));
      await tester.pump();
      expect(find.text('From this computer'), findsOneWidget);
      expect(find.text('From Jellyfin'), findsOneWidget);
      await tester.tap(find.text('From Jellyfin'));
      await tester.pump();
      expect((files, jellyfin), (0, 1));
      expect(find.text('From Jellyfin'), findsNothing);
      await tester.tap(find.text('Add'));
      await tester.pump();
      await tester.tap(find.text('From this computer'));
      await tester.pump();
      expect((files, jellyfin), (1, 1));
    });

    testWidgets('offers only this computer without a Jellyfin picker', (
      tester,
    ) async {
      useWindow(tester, desktopSizes.first);
      await pumpRoom(tester, video());
      await tester.tap(find.text('Add'));
      await tester.pump();
      expect(find.text('From this computer'), findsOneWidget);
      expect(find.text('From Jellyfin'), findsNothing);
    });

    testWidgets('a Jellyfin pick is queued and remembered under its own ref', (
      tester,
    ) async {
      useWindow(tester, desktopSizes.first);
      final known = <String, ({String name, int? durationMs})>{};
      final sent = <(String, Map<String, Object?>)>[];
      void send(String op, Map<String, Object?> args) => sent.add((op, args));
      await pumpRoom(
        tester,
        video(),
        onAddToQueue: () =>
            queuePicked(() async => hostCopy, known: known, send: send),
        onQueueJellyfin: () =>
            queuePicked(() async => jellyCopy, known: known, send: send),
      );
      await tester.tap(find.text('Add'));
      await tester.pump();
      await tester.tap(find.text('From Jellyfin'));
      await tester.pump();
      expect(sent, hasLength(1));
      expect(sent.single.$1, 'queue_add');
      expect(sent.single.$2, {'item_ref': jellyRef});
      expect(known[jellyRef], (name: 'sample-room', durationMs: 20000));

      // The file route ends in the same intent.
      await tester.tap(find.text('Add'));
      await tester.pump();
      await tester.tap(find.text('From this computer'));
      await tester.pump();
      expect(sent, hasLength(2));
      expect(sent.last.$1, 'queue_add');
      expect(sent.last.$2, {'item_ref': hostRef});
      expect(known[hostRef], (
        name: 'movie-night_1080p.mkv',
        durationMs: hostCopy.duration!.inMilliseconds,
      ));
    });

    test('a cancelled pick queues nothing', () async {
      final known = <String, ({String name, int? durationMs})>{};
      final sent = <(String, Map<String, Object?>)>[];
      await queuePicked(
        () async => null,
        known: known,
        send: (op, args) => sent.add((op, args)),
      );
      expect(sent, isEmpty);
      expect(known, isEmpty);
    });

    testWidgets('Add is disabled while disconnected', (tester) async {
      useWindow(tester, desktopSizes.first);
      await pumpRoom(tester, video(connected: false), onQueueJellyfin: () {});
      await tester.tap(find.text('Add'), warnIfMissed: false);
      await tester.pump();
      expect(find.text('From Jellyfin'), findsNothing);
    });

    testWidgets('queue rows carry the Jellyfin or Local file chip', (
      tester,
    ) async {
      useWindow(tester, desktopSizes.first);
      await pumpRoom(tester, video());
      // video(): a local file now playing, a Jellyfin item up next; the dock shows no chip.
      expect(find.text('Local file'), findsOneWidget);
      expect(find.text('Jellyfin'), findsOneWidget);
      expect(tester.takeException(), isNull);
    });
  });

  testWidgets('empty room: open-file stage, dimmed dock, nothing queued', (
    tester,

