1	/// Jellyfin as a media source. The room carries only `jellyfin:<host>/<itemId>`; every client
2	/// streams the item from its own Jellyfin with its own token. The room server never sees media.
3	library;
4	
5	import 'dart:async';
6	import 'dart:convert';
7	import 'dart:io';
8	
9	import 'package:crypto/crypto.dart';
10	
11	import 'protocol.dart';
12	
13	const String jellyfinClient = 'do2gether';
14	const String jellyfinVersion = '0.1.0';
15	
16	final RegExp _refParts = RegExp(
17	  r'^jellyfin:([A-Za-z0-9.-]+(?::[0-9]{1,5})?)/([0-9a-f]{32})$',
18	);
19	final RegExp _itemId = RegExp(r'^[0-9a-f]{32}$');
20	
21	/// `jellyfin:<host>[:<port>]/<32 lowercase hex itemId>` split into its parts; null otherwise.
22	({String host, String itemId})? parseJellyfinRef(String ref) {
23	  final m = _refParts.firstMatch(ref);
24	  if (m == null || !isItemRef(ref)) return null;
25	  return (host: m[1]!, itemId: m[2]!);
26	}
27	
28	/// The ref for [itemId] on [server]: its host, plus the port only when the URL spells one out.
29	String jellyfinRef(Uri server, String itemId) =>
30	    'jellyfin:${server.hasPort ? '${server.host}:${server.port}' : server.host}/$itemId';
31	
32	/// Direct play, no transcoding: `{server}/Videos/{itemId}/stream?static=true&api_key={token}`.
33	String streamUrl({
34	  required String server,
35	  required String token,
36	  required String itemId,
37	}) =>
38	    '${server.replaceFirst(RegExp(r'/+$'), '')}/Videos/$itemId/stream'
39	    '?static=true&api_key=${Uri.encodeQueryComponent(token)}';
40	
41	String? validateJellyfinServer(String? value) {
42	  final uri = Uri.tryParse((value ?? '').trim());
43	  if (uri == null ||
44	      (uri.scheme != 'http' && uri.scheme != 'https') ||
45	      uri.host.isEmpty) {
46	    return 'Enter an http:// or https:// server URL';
47	  }
48	  if (!isItemRef(jellyfinRef(uri, '0' * 32))) {
49	    return 'Use a host name or IPv4 address everyone in the room can reach';
50	  }
51	  return null;
52	}
53	
54	/// Jellyfin counts runtime in 100 ns ticks.
55	Duration ticksToDuration(int ticks) => Duration(microseconds: ticks ~/ 10);
56	
57	/// Same id on every run, so signing in again replaces this machine's Jellyfin session.
58	String jellyfinDeviceId([String? hostname]) => sha256
59	    .convert(utf8.encode('do2gether:${hostname ?? Platform.localHostname}'))
60	    .toString()
61	    .substring(0, 32);
62	
63	/// The `MediaBrowser` header. This server answers 401 to `X-Emby-Token` and to `?api_key=` on
64	/// `/Items`; the token has to ride in here.
65	String jellyfinAuthorization({String? token}) =>
66	    'MediaBrowser Client="$jellyfinClient", Device="desktop", '
67	    'DeviceId="${jellyfinDeviceId()}", Version="$jellyfinVersion"'
68	    '${token == null ? '' : ', Token="$token"'}';
69	
70	/// A failed Jellyfin call, carrying the server's own words.
71	class JellyfinException implements Exception {
72	  const JellyfinException(this.message, {this.status});
73	  final String message;
74	  final int? status;
75	
76	  @override
77	  String toString() => status == null ? message : '$message (HTTP $status)';
78	}
79	
80	class JellyfinItem {
81	  const JellyfinItem({required this.id, required this.name, this.runtime});
82	  final String id;
83	  final String name;
84	  final Duration? runtime;
85	}
86	
87	/// `GET /Items` → movies with a usable id. Items without `RunTimeTicks` get no runtime.
88	List<JellyfinItem> parseItems(Object? json) {
89	  final items = switch (json) {
90	    {'Items': final List<Object?> items} => items,
91	    _ => const <Object?>[],
92	  };
93	  return [
94	    for (final item in items)
95	      if (item case final Map<String, Object?> m)
96	        if (m case {'Id': final String id, 'Name': final String name}
97	            when _itemId.hasMatch(id))
98	          JellyfinItem(
99	            id: id,
100	            name: name,
101	            runtime: switch (m['RunTimeTicks']) {
102	              final int ticks when ticks > 0 => ticksToDuration(ticks),
103	              _ => null,
104	            },
105	          ),
106	  ];
107	}
108	
109	/// A signed-in user on one Jellyfin server.
110	class JellyfinSession {
111	  const JellyfinSession({
112	    required this.server,
113	    required this.token,
114	    required this.user,
115	  });
116	  final Uri server;
117	  final String token;
118	  final String user;
119	
120	  Future<List<JellyfinItem>> movies() async {
121	    final (status, body) = await _send(
122	      'GET',
123	      _endpoint(server, '/Items', const {
124	        'Recursive': 'true',
125	        'IncludeItemTypes': 'Movie',
126	        'Limit': '100',
127	        'SortBy': 'SortName',
128	      }),
129	      auth: jellyfinAuthorization(token: token),
130	    );
131	    if (status != HttpStatus.ok) throw _failure(status, body);
132	    return parseItems(_decode(body));
133	  }
134	}
135	
136	Future<JellyfinSession> signIn({
137	  required Uri server,
138	  required String user,
139	  required String pass,
140	}) async {
141	  final (status, body) = await _send(
142	    'POST',
143	    _endpoint(server, '/Users/AuthenticateByName'),
144	    auth: jellyfinAuthorization(),
145	    json: {'Username': user, 'Pw': pass},
146	  );
147	  if (status != HttpStatus.ok) throw _failure(status, body);
148	  if (_decode(body) case {'AccessToken': final String token}
149	      when token.isNotEmpty) {
150	    return JellyfinSession(server: server, token: token, user: user);
151	  }
152	  throw const JellyfinException('Jellyfin signed in but sent no access token');
153	}
154	
155	typedef JellyfinConfig = ({String server, String token, String user});
156	
157	/// `~/.config/do2gether/jellyfin.json`, or `%APPDATA%\do2gether\jellyfin.json` on Windows.
158	String jellyfinConfigPath({Map<String, String>? environment, bool? windows}) {
159	  final env = environment ?? Platform.environment;
160	  return (windows ?? Platform.isWindows)
161	      ? '${env['APPDATA'] ?? ''}\\do2gether\\jellyfin.json'
162	      : '${env['HOME'] ?? ''}/.config/do2gether/jellyfin.json';
163	}
164	
165	/// The saved sign-in, or null when there is none or it does not parse.
166	Future<JellyfinConfig?> loadJellyfinConfig(String path) async {
167	  try {
168	    final json = jsonDecode(await File(path).readAsString());
169	    if (json case {
170	      'server': final String server,
171	      'token': final String token,
172	      'user': final String user,
173	    }) {
174	      return (server: server, token: token, user: user);
175	    }
176	  } on FileSystemException {
177	    return null;
178	  } on FormatException {
179	    return null;
180	  }
181	  return null;
182	}
183	
184	/// Writes the sign-in, readable by this user only where the OS has modes.
185	Future<void> saveJellyfinConfig(String path, JellyfinConfig config) async {
186	  final file = File(path);
187	  await file.parent.create(recursive: true);
188	  await file.writeAsString(
189	    jsonEncode({
190	      'server': config.server,
191	      'token': config.token,
192	      'user': config.user,
193	    }),
194	  );
195	  if (!Platform.isWindows) await Process.run('chmod', ['600', path]);
196	}
197	
198	/// Sign-in plus the saved config, behind one seam so Home can be tested offline.
199	abstract interface class JellyfinApi {
200	  /// The session saved on this machine, or null when nobody has signed in.
201	  Future<JellyfinSession?> restore();
202	
203	  /// Signs in and saves the session for next time.
204	  Future<JellyfinSession> connect({
205	    required Uri server,
206	    required String user,
207	    required String pass,
208	  });
209	}
210	
211	class HttpJellyfinApi implements JellyfinApi {
212	  const HttpJellyfinApi({this.configPath});
213	
214	  /// Overrides [jellyfinConfigPath].
215	  final String? configPath;
216	
217	  String get _path => configPath ?? jellyfinConfigPath();
218	
219	  @override
220	  Future<JellyfinSession?> restore() async {
221	    final config = await loadJellyfinConfig(_path);
222	    final server = config == null ? null : Uri.tryParse(config.server);
223	    if (config == null || server == null) return null;
224	    return JellyfinSession(
225	      server: server,
226	      token: config.token,
227	      user: config.user,
