1	/// The Jellyfin dialog on Home: sign in, then pick a movie as this viewer's copy.
2	library;
3	
4	import 'dart:async';
5	
6	import 'package:flutter/material.dart';
7	
8	import 'format.dart';
9	import 'jellyfin.dart';
10	import 'local_copy.dart';
11	import 'theme.dart';
12	import 'widgets/button.dart';
13	import 'widgets/chrome.dart';
14	import 'widgets/field.dart';
15	
16	/// Resolves to the picked movie as a remote copy, or null when closed. With a [session] it opens
17	/// on the movie list; without one, on the sign-in form.
18	Future<LocalCopy?> showJellyfinPicker(
19	  BuildContext context, {
20	  required JellyfinApi api,
21	  required JellyfinSession? session,
22	  required ValueChanged<JellyfinSession> onSession,
23	}) => showDialog<LocalCopy>(
24	  context: context,
25	  barrierColor: const Color(0x8C000000),
26	  builder: (_) =>
27	      JellyfinDialog(api: api, session: session, onSession: onSession),
28	);
29	
30	class JellyfinDialog extends StatefulWidget {
31	  const JellyfinDialog({
32	    super.key,
33	    required this.api,
34	    required this.session,
35	    required this.onSession,
36	  });
37	  final JellyfinApi api;
38	  final JellyfinSession? session;
39	
40	  /// A sign-in succeeded; Home keeps it so the next open goes straight to the list.
41	  final ValueChanged<JellyfinSession> onSession;
42	
43	  @override
44	  State<JellyfinDialog> createState() => _JellyfinDialogState();
45	}
46	
47	class _JellyfinDialogState extends State<JellyfinDialog> {
48	  late JellyfinSession? _session = widget.session;
49	  late final _server = TextEditingController(
50	    text: widget.session?.server.toString() ?? '',
51	  );
52	  late final _user = TextEditingController(text: widget.session?.user ?? '');
53	  final _pass = TextEditingController();
54	  late bool _busy = widget.session != null;
55	  String? _error;
56	  List<JellyfinItem> _movies = const [];
57	
58	  static const _muted = TextStyle(
59	    fontSize: 14,
60	    fontWeight: FontWeight.w500,
61	    color: WtColors.tx3,
62	  );
63	
64	  @override
65	  void initState() {
66	    super.initState();
67	    if (_session != null) unawaited(_fetchMovies());
68	  }
69	
70	  @override
71	  void dispose() {
72	    _server.dispose();
73	    _user.dispose();
74	    _pass.dispose();
75	    super.dispose();
76	  }
77	
78	  Future<void> _connect() async {
79	    final problem =
80	        validateJellyfinServer(_server.text) ??
81	        (_user.text.trim().isEmpty ? 'Enter your Jellyfin user name' : null);
82	    if (problem != null) {
83	      setState(() => _error = problem);
84	      return;
85	    }
86	    setState(() {
87	      _busy = true;
88	      _error = null;
89	    });
90	    try {
91	      final session = await widget.api.connect(
92	        server: Uri.parse(_server.text.trim()),
93	        user: _user.text.trim(),
94	        pass: _pass.text,
95	      );
96	      if (!mounted) return;
97	      widget.onSession(session);
98	      setState(() => _session = session);
99	      await _fetchMovies();
100	    } on Object catch (e) {
101	      if (mounted) {
102	        setState(() {
103	          _busy = false;
104	          _error = '$e';
105	        });
106	      }
107	    }
108	  }
109	
110	  Future<void> _fetchMovies() async {
111	    try {
112	      final movies = await _session!.movies();
113	      if (mounted) {
114	        setState(() {
115	          _movies = movies;
116	          _busy = false;
117	        });
118	      }
119	    } on Object catch (e) {
120	      // A saved token can be revoked: back to the form, with the server's words.
121	      if (mounted) {
122	        setState(() {
123	          _session = null;
124	          _busy = false;
125	          _error = '$e';
126	        });
127	      }
128	    }
129	  }
130	
131	  void _signInAgain() => setState(() {
132	    _session = null;
133	    _pass.clear();
134	    _error = null;
135	  });
136	
137	  void _pick(JellyfinItem item) {
138	    final session = _session!;
139	    Navigator.of(context).pop(
140	      LocalCopy.remote(
141	        url: streamUrl(
142	          server: session.server.toString(),
143	          token: session.token,
144	          itemId: item.id,
145	        ),
146	        itemRef: jellyfinRef(session.server, item.id),
147	        title: item.name,
148	        duration: item.runtime,
149	      ),
150	    );
151	  }
152	
153	  @override
154	  Widget build(BuildContext context) {
155	    final session = _session;
156	    return Dialog(
157	      backgroundColor: WtColors.plum2,
158	      shape: RoundedRectangleBorder(
159	        borderRadius: BorderRadius.circular(WtRadius.surface),
160	        side: const BorderSide(color: WtColors.line, width: 2),
161	      ),
162	      child: SizedBox(
163	        width: 460,
164	        child: Padding(
165	          padding: const EdgeInsets.fromLTRB(24, 20, 24, 20),
166	          child: Column(
167	            mainAxisSize: MainAxisSize.min,
168	            crossAxisAlignment: CrossAxisAlignment.stretch,
169	            children: [
170	              Row(
171	                children: [
172	                  Expanded(
173	                    child: Text(
174	                      'Jellyfin',
175	                      style: Theme.of(context).textTheme.titleLarge,
176	                    ),
177	                  ),
178	                  WtIconButton(
179	                    icon: Icons.close_rounded,
180	                    tooltip: 'Close',
181	                    onPressed: () => Navigator.of(context).pop(),
182	                  ),
183	                ],
184	              ),
185	              const SizedBox(height: 4),
186	              if (session == null)
187	                const Text(
188	                  'Everyone streams from their own server. '
189	                  'The room only shares which movie.',
190	                  style: _muted,
191	                )
192	              else
193	                Row(
194	                  children: [
195	                    Expanded(
196	                      child: Text(
197	                        'Signed in as ${session.user} on ${session.server.host}',
198	                        maxLines: 1,
199	                        overflow: TextOverflow.ellipsis,
200	                        style: _muted,
201	                      ),
202	                    ),
203	                    WtTextButton(
204	                      label: 'Change',
205	                      compact: true,
206	                      onPressed: _busy ? null : _signInAgain,
207	                    ),
208	                  ],
209	                ),
210	              const SizedBox(height: 16),
211	              if (session == null) ..._form() else ..._list(),
212	            ],
213	          ),
214	        ),
215	      ),
216	    );
217	  }
218	
219	  List<Widget> _form() => [
220	    Flexible(
221	      child: SingleChildScrollView(
222	        child: Column(
223	          crossAxisAlignment: CrossAxisAlignment.stretch,
224	          children: [
225	            const WtLabel('Server'),
226	            const SizedBox(height: 8),
227	            WtField(
228	              controller: _server,
229	              hint: 'https://jellyfin.example',
230	              icon: Icons.dns_outlined,
231	              height: 56,
232	              autofocus: _server.text.isEmpty,
233	              onChanged: _clearError,
234	              onSubmitted: (_) => _connect(),
235	            ),
236	            const SizedBox(height: 14),
237	            const WtLabel('User'),
238	            const SizedBox(height: 8),
239	            WtField(
240	              controller: _user,
241	              hint: 'Your Jellyfin user',
242	              icon: Icons.person_outline,
243	              height: 56,
244	              onChanged: _clearError,
245	              onSubmitted: (_) => _connect(),
246	            ),
247	            const SizedBox(height: 14),
248	            const WtLabel('Password'),
249	            const SizedBox(height: 8),
250	            WtField(
251	              controller: _pass,
252	              hint: 'Leave empty if there is none',
253	              icon: Icons.lock_outline,
254	              height: 56,
255	              obscure: true,
256	              autofocus: _server.text.isNotEmpty,
257	              onChanged: _clearError,
258	              onSubmitted: (_) => _connect(),
259	            ),
260	            if (_error != null) ...[
261	              const SizedBox(height: 10),
262	              _ErrorText(_error!),
263	            ],
264	          ],
265	        ),
266	      ),
267	    ),
268	    const SizedBox(height: 20),
269	    Align(
270	      alignment: Alignment.centerRight,
271	      child: WtButton(
272	        label: _busy ? 'Connecting…' : 'Connect',
273	        onPressed: _busy ? null : _connect,
274	      ),
275	    ),
276	  ];
277	
278	  List<Widget> _list() {
279	    if (_busy) {
280	      return const [Text('Loading movies…', style: _muted)];
281	    }
282	    if (_movies.isEmpty) {
283	      return const [Text('No movies on this server yet.', style: _muted)];
284	    }
285	    return [
286	      const WtLabel('Pick a movie'),
287	      const SizedBox(height: 8),
288	      Flexible(
289	        child: ConstrainedBox(
290	          constraints: const BoxConstraints(maxHeight: 380),
291	          child: ListView.separated(
292	            shrinkWrap: true,
293	            itemCount: _movies.length,
294	            separatorBuilder: (_, _) => const SizedBox(height: 8),
295	            itemBuilder: (_, i) =>
296	                _MovieRow(item: _movies[i], onTap: () => _pick(_movies[i])),
297	          ),
298	        ),
299	      ),
300	    ];
301	  }
302	
303	  void _clearError(String _) {
304	    if (_error != null) setState(() => _error = null);
305	  }
306	}
307	
308	class _ErrorText extends StatelessWidget {
309	  const _ErrorText(this.text);
310	  final String text;
311	
312	  @override
313	  Widget build(BuildContext context) => Text(
314	    text,
315	    style: const TextStyle(
316	      fontSize: 13,
317	      fontWeight: FontWeight.w700,
318	      color: WtColors.yellow,
319	    ),
