  upNext: const [
    (
      title: 'episode-02_1080p.mkv',
      detail: '24:10',
      source: MediaSource.jellyfin,
    ),
  ],
  stage: StageMode.video,
  fileName: 'movie-night_1080p.mkv',
  positionMs: 724000,
  durationMs: 6730000,
  bufferedMs: 900000,
  playing: playing,
  pause: pause,
  waitingFor: waitingFor,
  fullscreen: fullscreen,
  aspect: aspect,
);

