124	  @override
125	  void initState() {
126	    super.initState();
127	    _client = _connect(widget.clientId);
128	    _pollTimer = Timer.periodic(pollEvery, (_) => _poll());
129	    _reportTimer = Timer.periodic(reportEvery, (_) => _report());
130	    final stream = _player.player.stream;
131	    void refresh(Object _) {
132	      if (mounted) setState(() {});
133	    }
134	
135	    _subs.addAll([
136	      stream.error.listen((e) {
137	        if (mounted) setState(() => _playerError = e);
138	      }),
139	      stream.buffering.listen(refresh),
140	      stream.completed.listen(refresh),
141	      stream.tracks.listen(refresh),
142	    ]);
143	    _player.player.setVolume(_volume);
144	    final initial = widget.initialCopy;
145	    if (initial != null) {
146	      initial.isRemote ? _openRemote(initial) : _openPath(initial.path);
147	    }
148	  }
149	
150	  @override
151	  void dispose() {
152	    _pollTimer.cancel();
153	    _reportTimer.cancel();
154	    _retryTimer?.cancel();
155	    for (final s in _subs) {
156	      s.cancel();
157	    }
158	    _client.close();
159	    _player.dispose();
160	    if (_fullscreen) defaultExitNativeFullscreen();
161	    super.dispose();
162	  }
