324	  Future<void> _open(
325	    Future<void> Function() open, {
326	    required String name,
327	    required MediaSource source,
328	    int? durationMs,
329	  }) async {
330	    final attempt = (
331	      name: name,
332	      source: source,
333	      open: () => _open(open, name: name, source: source, durationMs: durationMs),
334	    );
335	    setState(() {
336	      _attempt = attempt;
337	      _opening = true;
338	      _openError = null;
339	      _playerError = null;
340	    });
341	    try {
342	      await open();
343	      final ref = _player.itemRef;
344	      if (ref != null) _known[ref] = (name: name, durationMs: durationMs);
345	    } on Object catch (e) {
346	      // Never the raw text: a stream URL carries the viewer's token.
347	      if (mounted) setState(() => _openError = playerErrorReason('$e'));
348	    } finally {
349	      if (mounted) setState(() => _opening = false);
350	    }
351	    await _apply();
352	  }
