          left: -5,
          top: -5,
          right: -5,
          bottom: -5,
          child: IgnorePointer(
            child: DecoratedBox(
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(radius + 5),
                border: Border.all(color: WtColors.cyan, width: 2),
              ),
            ),
          ),
        ),
    ],
  );
}

/// Shared interaction for every tappable surface: click cursor, Enter activates,
/// pressed scale .96 over 120 ms, focus ring, 40% when disabled.
class WtTap extends StatefulWidget {
  const WtTap({
    super.key,
    required this.child,
    required this.onTap,
    this.radius = WtRadius.control,
    this.tooltip,
    this.semanticLabel,
    this.dimWhenDisabled = true,
  });
  final Widget child;
  final VoidCallback? onTap;
  final double radius;
  final String? tooltip;
  final String? semanticLabel;
  final bool dimWhenDisabled;

  @override
  State<WtTap> createState() => _WtTapState();
}

class _WtTapState extends State<WtTap> {
  bool _focused = false;
  bool _pressed = false;

  void _press(bool value) {
    if (_pressed != value) setState(() => _pressed = value);
  }

  @override
  Widget build(BuildContext context) {
    final enabled = widget.onTap != null;
    Widget child = FocusableActionDetector(
      enabled: enabled,
      mouseCursor: enabled ? SystemMouseCursors.click : MouseCursor.defer,
      onShowFocusHighlight: (v) => setState(() => _focused = v),
      actions: {
        ActivateIntent: CallbackAction<ActivateIntent>(
          onInvoke: (_) {
            widget.onTap?.call();
            return null;
          },
        ),
      },
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTapDown: enabled ? (_) => _press(true) : null,
        onTapUp: enabled ? (_) => _press(false) : null,
        onTapCancel: () => _press(false),
        onTap: widget.onTap,
        child: AnimatedScale(
          scale: _pressed ? 0.96 : 1,
          duration: const Duration(milliseconds: 120),
          curve: Curves.easeOut,
          child: WtFocusRing(
            show: _focused && enabled,
            radius: widget.radius,
            child: widget.child,
          ),
        ),
      ),
    );
    child = Semantics(
      button: true,
      enabled: enabled,
      label: widget.semanticLabel,
      child: child,
    );
    if (widget.tooltip != null) {
      child = Tooltip(message: widget.tooltip!, child: child);
    }
    return widget.dimWhenDisabled && !enabled
        ? Opacity(opacity: 0.4, child: child)
        : child;
  }
}

