281	  group('queue Add', () {
282	    const jellyRef = 'jellyfin:jelly.example/$jellyItemId';
283	    const jellyCopy = LocalCopy.remote(
284	      url: 'http://jelly.example/Videos/$jellyItemId/stream?api_key=secret',
285	      itemRef: jellyRef,
286	      title: 'sample-room',
287	      duration: Duration(seconds: 20),
288	    );
289	
290	    testWidgets('offers this computer and Jellyfin when a picker exists', (
291	      tester,
292	    ) async {
293	      useWindow(tester, desktopSizes.first);
294	      var files = 0;
295	      var jellyfin = 0;
296	      await pumpRoom(
297	        tester,
298	        video(),
299	        onAddToQueue: () => files++,
300	        onQueueJellyfin: () => jellyfin++,
301	      );
302	      expect(find.text('From this computer'), findsNothing);
303	      await tester.tap(find.text('Add'));
304	      await tester.pump();
305	      expect(find.text('From this computer'), findsOneWidget);
306	      expect(find.text('From Jellyfin'), findsOneWidget);
307	      await tester.tap(find.text('From Jellyfin'));
308	      await tester.pump();
309	      expect((files, jellyfin), (0, 1));
310	      expect(find.text('From Jellyfin'), findsNothing);
311	      await tester.tap(find.text('Add'));
312	      await tester.pump();
313	      await tester.tap(find.text('From this computer'));
314	      await tester.pump();
315	      expect((files, jellyfin), (1, 1));
316	    });
317	
318	    testWidgets('offers only this computer without a Jellyfin picker', (
319	      tester,
320	    ) async {
321	      useWindow(tester, desktopSizes.first);
322	      await pumpRoom(tester, video());
323	      await tester.tap(find.text('Add'));
324	      await tester.pump();
325	      expect(find.text('From this computer'), findsOneWidget);
326	      expect(find.text('From Jellyfin'), findsNothing);
327	    });
328	
329	    testWidgets('a Jellyfin pick is queued and remembered under its own ref', (
330	      tester,
331	    ) async {
332	      useWindow(tester, desktopSizes.first);
333	      final known = <String, ({String name, int? durationMs})>{};
334	      final sent = <(String, Map<String, Object?>)>[];
335	      void send(String op, Map<String, Object?> args) => sent.add((op, args));
336	      await pumpRoom(
337	        tester,
338	        video(),
339	        onAddToQueue: () =>
340	            queuePicked(() async => hostCopy, known: known, send: send),
341	        onQueueJellyfin: () =>
342	            queuePicked(() async => jellyCopy, known: known, send: send),
343	      );
344	      await tester.tap(find.text('Add'));
345	      await tester.pump();
346	      await tester.tap(find.text('From Jellyfin'));
347	      await tester.pump();
348	      expect(sent, hasLength(1));
349	      expect(sent.single.$1, 'queue_add');
350	      expect(sent.single.$2, {'item_ref': jellyRef});
351	      expect(known[jellyRef], (name: 'sample-room', durationMs: 20000));
352	
353	      // The file route ends in the same intent.
354	      await tester.tap(find.text('Add'));
355	      await tester.pump();
356	      await tester.tap(find.text('From this computer'));
357	      await tester.pump();
358	      expect(sent, hasLength(2));
359	      expect(sent.last.$1, 'queue_add');
360	      expect(sent.last.$2, {'item_ref': hostRef});
361	      expect(known[hostRef], (
362	        name: 'movie-night_1080p.mkv',
363	        durationMs: hostCopy.duration!.inMilliseconds,
364	      ));
365	    });
366	
367	    test('a cancelled pick queues nothing', () async {
368	      final known = <String, ({String name, int? durationMs})>{};
369	      final sent = <(String, Map<String, Object?>)>[];
370	      await queuePicked(
