397	  /// Ctrl+V anywhere on Home pastes the invite, unless a text field already has focus.
398	  KeyEventResult _onKey(FocusNode node, KeyEvent event) {
399	    if (event is! KeyDownEvent ||
400	        event.logicalKey != LogicalKeyboardKey.keyV ||
401	        !HardwareKeyboard.instance.isControlPressed) {
402	      return KeyEventResult.ignored;
403	    }
404	    final focused = FocusManager.instance.primaryFocus?.context;
405	    if (focused?.findAncestorWidgetOfExactType<EditableText>() != null) {
406	      return KeyEventResult.ignored;
407	    }
408	    unawaited(_paste());
409	    return KeyEventResult.handled;
