1	/// The library: one full-height surface for picking what to play or queue. Tabs, cards and empty
2	/// states are built from the registered [MediaSource]s, so a new source is a new tab and nothing
3	/// here changes.
4	library;
5	
6	import 'dart:async';
7	import 'dart:math' as math;
8	
9	import 'package:flutter/material.dart';
10	import 'package:flutter/services.dart';
11	
12	import 'format.dart';
13	import 'local_copy.dart';
14	import 'media.dart';
15	import 'theme.dart';
16	import 'widgets/button.dart';
17	import 'widgets/chrome.dart';
18	import 'widgets/field.dart';
19	
20	/// `play` closes on the first pick with that item's copy; `queue` hands every pick to `onQueue` and
21	/// stays open so several can be added.
22	enum LibraryMode { play, queue }
23	
24	/// Art for a poster URL; tests swap in memory images.
25	typedef PosterImage = ImageProvider Function(String url);
26	
27	ImageProvider networkPoster(String url) => NetworkImage(url);
28	
29	/// Resolves to the picked item's copy in [LibraryMode.play]; null when closed, and always null in
30	/// [LibraryMode.queue].
31	Future<LocalCopy?> showMediaLibrary(
32	  BuildContext context, {
33	  required List<MediaSource> sources,
34	  LibraryMode mode = LibraryMode.play,
35	  MediaSourceKind? initial,
36	  ValueChanged<MediaItem>? onQueue,
37	  PosterImage poster = networkPoster,
38	}) => Navigator.of(context).push<LocalCopy>(
39	  wtRoute(
40	    MediaLibrary(
41	      sources: sources,
42	      mode: mode,
43	      initial: initial,
44	      onQueue: onQueue,
45	      poster: poster,
46	    ),
47	  ),
48	);
49	
50	class MediaLibrary extends StatefulWidget {
51	  const MediaLibrary({
52	    super.key,
53	    required this.sources,
54	    this.mode = LibraryMode.play,
55	    this.initial,
56	    this.onQueue,
57	    this.poster = networkPoster,
58	  }) : assert(mode == LibraryMode.play || onQueue != null);
59	
60	  /// The tabs, in order.
61	  final List<MediaSource> sources;
62	  final LibraryMode mode;
63	
64	  /// The tab to open on; the first available source when null or not available.
65	  final MediaSourceKind? initial;
66	
67	  /// Adds an item to the room's queue. In play mode a non-null value puts `Queue` beside `Play`.
68	  final ValueChanged<MediaItem>? onQueue;
69	  final PosterImage poster;
70	
71	  @override
72	  State<MediaLibrary> createState() => _MediaLibraryState();
73	}
74	
75	class _MediaLibraryState extends State<MediaLibrary> {
76	  final _query = TextEditingController();
77	  final _search = FocusNode(debugLabel: 'library search');
78	  final _keys = FocusNode(debugLabel: 'library');
79	  final _scroll = ScrollController();
80	  late int _tab = _initialTab();
81	
82	  /// Null while the tab loads.
83	  List<MediaItem>? _items;
84	  Object? _error;
85	  int _seq = 0;
86	  int? _selected;
87	
88	  /// The ref being opened, or the label of the action running; other actions wait for it.
89	  String? _busy;
90	  final Set<String> _queued = {};
91	  int _columns = 1;
92	  double _rowExtent = 0;
93	
94	  static const _connecting = 'connect';
95	  static const _muted = TextStyle(
96	    fontSize: 14,
97	    height: 1.45,
98	    fontWeight: FontWeight.w600,
99	    color: WtColors.tx3,
100	  );
101	
102	  bool get _queueMode => widget.mode == LibraryMode.queue;
103	  MediaSource get _source => widget.sources[_tab];
104	
105	  int _initialTab() {
106	    final sources = widget.sources;
107	    final wanted = sources.indexWhere(
108	      (s) => s.kind == widget.initial && s.available,
109	    );
110	    if (wanted >= 0) return wanted;
111	    return math.max(0, sources.indexWhere((s) => s.available));
112	  }
113	
114	  @override
115	  void initState() {
116	    super.initState();
117	    unawaited(_fetch());
118	  }
119	
120	  @override
121	  void dispose() {
122	    _query.dispose();
123	    _search.dispose();
124	    _keys.dispose();
125	    _scroll.dispose();
126	    super.dispose();
127	  }
128	
129	  /// [fresh] blanks the grid while it loads (a tab switch); a search keeps the old cards up until
130	  /// the new ones arrive.
131	  void _reload({bool fresh = true}) {
132	    setState(() {
133	      if (fresh) _items = null;
134	      _error = null;
135	      _selected = null;
136	    });
137	    unawaited(_fetch());
138	  }
139	
140	  Future<void> _fetch() async {
141	    final source = _source;
142	    final seq = ++_seq;
143	    try {
144	      final items = source.available && source.ready
145	          ? await source.browse(query: _query.text)
146	          : const <MediaItem>[];
147	      if (mounted && seq == _seq) setState(() => _items = items);
148	    } on Object catch (e) {
149	      if (mounted && seq == _seq) {
150	        setState(() {
151	          _items = const [];
152	          _error = e;
153	        });
154	      }
155	    }
156	  }
157	
158	  void _pickTab(int i) {
159	    if (i == _tab || !widget.sources[i].available) return;
160	    _tab = i;
161	    _reload();
162	  }
163	
164	  void _say(String message) => ScaffoldMessenger.of(
165	    context,
166	  ).showSnackBar(SnackBar(content: Text(message)));
167	
168	  Future<void> _connect() async {
169	    final source = _source;
170	    setState(() => _busy = _connecting);
171	    try {
172	      await source.ensureReady();
173	    } on Object catch (e) {
174	      if (mounted) _say("Couldn't connect ${source.label}: $e");
175	    } finally {
176	      if (mounted) setState(() => _busy = null);
177	    }
178	    if (mounted && identical(source, _source)) _reload();
179	  }
180	
181	  Future<void> _run(MediaSourceAction action) async {
182	    setState(() => _busy = action.label);
183	    MediaItem? item;
184	    try {
185	      item = await action.run();
186	    } on Object catch (e) {
187	      if (mounted) _say("Couldn't open that: $e");
188	    } finally {
189	      if (mounted) setState(() => _busy = null);
190	    }
191	    if (!mounted) return;
192	    _reload(fresh: false);
193	    if (item != null) await _primary(item);
194	  }
195	
196	  /// `Play` or `Queue this`, whichever the mode makes the main action.
197	  Future<void> _primary(MediaItem item) async {
198	    if (_queueMode) {
199	      _queue(item);
200	    } else {
201	      await _play(item);
202	    }
203	  }
204	
205	  void _queue(MediaItem item) {
206	    widget.onQueue!(item);
207	    setState(() => _queued.add(item.ref));
208	  }
209	
210	  Future<void> _play(MediaItem item) async {
211	    final source = widget.sources.firstWhere((s) => s.kind == item.source);
212	    setState(() => _busy = item.ref);
213	    try {
214	      final copy = await source.open(item);
215	      if (!mounted) return;
216	      if (copy == null) {
217	        _say("Couldn't open ${item.title} any more. Pick it again.");
218	        return;
219	      }
220	      Navigator.of(context).pop(copy);
221	    } on Object catch (e) {
222	      if (mounted) _say("Couldn't open ${item.title}: $e");
223	    } finally {
224	      if (mounted) setState(() => _busy = null);
225	    }
226	  }
227	
228	  void _select(int i) {
229	    setState(() => _selected = i);
230	    if (!_scroll.hasClients || _rowExtent <= 0) return;
231	    final pos = _scroll.position;
232	    final top = (i ~/ _columns) * _rowExtent;
233	    final bottom = top + _rowExtent;
234	    final target = top < pos.pixels
235	        ? top
236	        : bottom > pos.pixels + pos.viewportDimension
237	        ? bottom - pos.viewportDimension
238	        : null;
239	    if (target != null) {
240	      _scroll.jumpTo(target.clamp(pos.minScrollExtent, pos.maxScrollExtent));
241	    }
242	  }
243	
244	  void _close() => unawaited(Navigator.of(context).maybePop());
245	
246	  /// `/` search, `Esc` close; arrows and `Enter` only while the grid itself has focus, so a focused
247	  /// button or the search field keeps its own keys.
248	  KeyEventResult _onKey(FocusNode node, KeyEvent event) {
249	    if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
250	      return KeyEventResult.ignored;
251	    }
252	    final key = event.logicalKey;
253	    if (key == LogicalKeyboardKey.escape) {
254	      _close();
255	      return KeyEventResult.handled;
256	    }
257	    final typing = _search.hasFocus;
258	    if (key == LogicalKeyboardKey.slash && !typing) {
259	      _search.requestFocus();
260	      return KeyEventResult.handled;
261	    }
262	    final items = _items ?? const <MediaItem>[];
263	    if (items.isEmpty) return KeyEventResult.ignored;
264	    if (typing && key == LogicalKeyboardKey.arrowDown) {
265	      _keys.requestFocus();
266	      _select(_selected ?? 0);
267	      return KeyEventResult.handled;
268	    }
269	    if (!_keys.hasPrimaryFocus) return KeyEventResult.ignored;
270	    final step = key == LogicalKeyboardKey.arrowLeft
271	        ? -1
272	        : key == LogicalKeyboardKey.arrowRight
273	        ? 1
274	        : key == LogicalKeyboardKey.arrowUp
275	        ? -_columns
276	        : key == LogicalKeyboardKey.arrowDown
277	        ? _columns
278	        : 0;
279	    final current = _selected;
280	    if (step != 0) {
281	      _select(
282	        current == null ? 0 : (current + step).clamp(0, items.length - 1),
283	      );
284	      return KeyEventResult.handled;
285	    }
286	    if ((key == LogicalKeyboardKey.enter ||
287	            key == LogicalKeyboardKey.numpadEnter) &&
288	        current != null) {
289	      if (_busy == null) unawaited(_primary(items[current]));
290	      return KeyEventResult.handled;
291	    }
292	    return KeyEventResult.ignored;
293	  }
294	
295	  @override
296	  Widget build(BuildContext context) => WtScaffold(
297	    child: Focus(
298	      focusNode: _keys,
299	      autofocus: true,
300	      onKeyEvent: _onKey,
301	      child: WtBackdrop(
302	        child: Padding(
303	          padding: const EdgeInsets.all(WtSpace.window),
304	          child: LayoutBuilder(
305	            builder: (context, box) {
306	              final narrow = box.maxWidth < 1000;
307	              return Column(
308	                crossAxisAlignment: CrossAxisAlignment.stretch,
309	                children: [
310	                  _header(narrow),
311	                  const SizedBox(height: 20),
312	                  _tabs(narrow),
313	                  const SizedBox(height: 18),
314	                  Expanded(child: _body()),
315	                ],
316	              );
317	            },
318	          ),
319	        ),
320	      ),
321	    ),
322	  );
323	
324	  Widget _header(bool narrow) {
325	    final title = Column(
326	      crossAxisAlignment: CrossAxisAlignment.start,
327	      mainAxisSize: MainAxisSize.min,
328	      children: [
329	        Text(
330	          _queueMode ? 'Add to queue' : 'Library',
331	          style: Theme.of(context).textTheme.headlineMedium,
332	        ),
333	        const SizedBox(height: 4),
334	        Text(
335	          _queueMode
336	              ? 'Queue as many as you like. Each one goes to the end.'
337	              : 'Pick what you will play. Everyone opens their own copy.',
338	          maxLines: 2,
339	          overflow: TextOverflow.ellipsis,
340	          style: _muted,
341	        ),
342	      ],
343	    );
344	    final search = WtField(
345	      controller: _query,
346	      focusNode: _search,
347	      hint: 'Search',
348	      icon: Icons.search_rounded,
349	      height: 52,
350	      onChanged: (_) => _reload(fresh: false),
351	      onSubmitted: (_) {
352	        if (_items?.isNotEmpty ?? false) {
353	          _keys.requestFocus();
354	          _select(_selected ?? 0);
355	        }
356	      },
357	      trailing: const _KeyHint('/'),
358	    );
359	    final end = [
360	      if (_queueMode && _queued.isNotEmpty) ...[
361	        WtPill(
362	          label: '${_queued.length} queued',
363	          tone: WtTone.live,
364	          icon: Icons.check_rounded,
365	          fontSize: 13,
366	        ),
367	        const SizedBox(width: 12),
368	      ],
369	      if (_queueMode)
370	        WtButton(label: 'Done', onPressed: _close)
371	      else
372	        WtIconButton(
373	          icon: Icons.close_rounded,
374	          tooltip: 'Close (Esc)',
375	          onPressed: _close,
376	        ),
377	    ];
378	    if (narrow) {
379	      return Column(
380	        crossAxisAlignment: CrossAxisAlignment.stretch,
381	        children: [
382	          Row(
383	            children: [
384	              Expanded(child: title),
385	              const SizedBox(width: 16),
386	              ...end,
387	            ],
388	          ),
389	          const SizedBox(height: 16),
390	          search,
391	        ],
392	      );
393	    }
394	    return Row(
395	      children: [
396	        Expanded(child: title),
397	        const SizedBox(width: 24),
