451	  Widget _body() {
452	    final source = _source;
453	    final items = _items;
454	    final error = _error;
455	    if (!source.ready) {
456	      return _EmptyState(
457	        icon: Icons.link_rounded,
458	        title: 'Not signed in to ${source.label}',
459	        body: error == null
460	            ? 'Sign in to browse it here. The room only ever shares which item, '
461	                  'never your account.'
462	            : '$error',
463	        actions: [
464	          WtButton(
465	            label: _busy == _connecting
466	                ? 'Connecting…'
467	                : 'Connect ${source.label}',
468	            icon: Icons.login_rounded,
469	            onPressed: _busy == null ? _connect : null,
470	          ),
471	        ],
472	      );
473	    }
474	    if (items == null) return _Loading(label: 'Loading ${source.label}…');
475	    if (error != null) {
476	      return _EmptyState(
477	        icon: Icons.cloud_off_outlined,
478	        title: "Couldn't load ${source.label}",
479	        body: '$error',
480	        actions: [
481	          WtButton(
482	            label: 'Try again',
483	            style: WtButtonStyle.ghost,
484	            onPressed: _reload,
485	          ),
486	        ],
487	      );
488	    }
489	    final query = _query.text.trim();
490	    if (items.isEmpty && query.isNotEmpty) {
491	      return _EmptyState(
492	        icon: Icons.search_off_rounded,
493	        title: 'No matches for “$query”',
494	        body: 'Try another word, or clear the search.',
495	        actions: [
496	          WtButton(
497	            label: 'Clear search',
498	            style: WtButtonStyle.ghost,
499	            onPressed: () {
500	              _query.clear();
501	              _reload(fresh: false);
502	            },
503	          ),
504	        ],
505	      );
506	    }
507	    if (items.isEmpty) {
508	      return _EmptyState(
509	        icon: Icons.video_library_outlined,
510	        title: 'Nothing in this library yet',
511	        body: source.emptyHint,
512	        actions: [
513	          for (final action in source.actions)
514	            WtButton(
515	              label: _busy == action.label ? 'Checking…' : action.label,
516	              icon: action.icon,
517	              onPressed: _busy == null ? () => _run(action) : null,
518	            ),
519	        ],
520	      );
521	    }
522	    return _grid(items);
523	  }
