525	  Widget _grid(List<MediaItem> items) => LayoutBuilder(
526	    builder: (context, box) {
527	      const gap = 18.0;
528	      const minTile = 168.0;
529	      const text = 58.0;
530	      // Room for the focus ring, which sits 5px outside the art.
531	      const edge = 6.0;
532	      final width = box.maxWidth - 2 * edge;
533	      final columns = ((width + gap) / (minTile + gap)).floor().clamp(2, 8);
534	      final tile = (width - gap * (columns - 1)) / columns;
535	      final extent = tile * 1.5 + text;
536	      _columns = columns;
537	      _rowExtent = extent + gap;
538	      return GridView.builder(
539	        controller: _scroll,
540	        padding: const EdgeInsets.all(edge),
541	        gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
542	          crossAxisCount: columns,
543	          mainAxisSpacing: gap,
544	          crossAxisSpacing: gap,
545	          mainAxisExtent: extent,
546	        ),
547	        itemCount: items.length,
548	        itemBuilder: (context, i) {
549	          final item = items[i];
550	          return _MediaCard(
551	            item: item,
552	            poster: widget.poster,
553	            selected: i == _selected,
554	            queued: _queued.contains(item.ref),
555	            busy: _busy == item.ref,
556	            queueMode: _queueMode,
557	            onSelect: () {
558	              _keys.requestFocus();
559	              setState(() => _selected = i);
560	            },
561	            onPlay: _queueMode || _busy != null ? null : () => _play(item),
562	            onQueue: widget.onQueue == null ? null : () => _queue(item),
563	          );
564	        },
565	      );
566	    },
567	  );
568	}
