17	import 'widgets/button.dart';
18	
19	const Duration pollEvery = Duration(seconds: 1);
20	const Duration reportEvery = Duration(seconds: 5);
21	
22	/// A pause we sent within this window is credited to "You" when the paused anchor arrives.
23	const Duration ownPauseWindow = Duration(seconds: 2);
24	
25	/// The volume level outlives a room for the rest of the app session; mute does not.
26	double _sessionVolume = 100;
27	
28	/// The copy we last tried to open: named on the error card and opened again by Try again.
29	typedef _Attempt = ({
30	  String name,
31	  MediaSource source,
32	  Future<void> Function() open,
33	});
34	
35	MediaSource _sourceOf(String ref) =>
36	    ref.startsWith('jellyfin:') ? MediaSource.jellyfin : MediaSource.local;
37	
38	/// Where both `Add` routes end, file or Jellyfin: the picked copy's name and duration are
39	/// remembered under its ref so the row reads as a title, then that ref is queued as-is.
40	Future<void> queuePicked(
41	  PickCopy pick, {
42	  required Map<String, ({String name, int? durationMs})> known,
43	  required void Function(String op, Map<String, Object?> args) send,
44	}) async {
45	  final copy = await pick();
46	  if (copy == null) return;
47	  known[copy.itemRef] = (
48	    name: copy.name,
49	    durationMs: copy.duration?.inMilliseconds,
50	  );
51	  send('queue_add', {'item_ref': copy.itemRef});
52	}
53	
54	class RoomScreen extends StatefulWidget {
55	  const RoomScreen({
56	    super.key,
57	    required this.server,
58	    required this.room,
59	    required this.token,
60	    required this.name,
61	    this.clientId,
62	    this.initialCopy,
63	    this.pickCopy = pickLocalCopy,
64	    this.pickJellyfin,
65	  });
66	
67	  final Uri server;
68	  final String room;
69	  final String token;
70	  final String name;
71	  final String? clientId;
72	
73	  /// The copy chosen on Home or in the room-ready dialog; opened on entry.
74	  final LocalCopy? initialCopy;
75	  final PickCopy pickCopy;
76	
77	  /// Opens the Jellyfin picker; null when the app has no Jellyfin support in this context.
78	  final PickCopy? pickJellyfin;
79	
80	  @override
81	  State<RoomScreen> createState() => _RoomScreenState();
82	}
83	
84	class _RoomScreenState extends State<RoomScreen> {
85	  late RoomClient _client;
86	  final SyncPlayer _player = SyncPlayer();
87	  late final Timer _pollTimer;
88	  late final Timer _reportTimer;
89	  final List<Member> _members = [];
90	  List<QueueItem> _queue = [];
91	  RoomMeta? _meta;
92	  int _rev = 0;
93	  Playback? _anchor;
94	  bool _clockWasReady = false;
95	  bool _opening = false;
96	  bool _muted = false;
97	  double _volume = _sessionVolume;
98	  bool _fullscreen = false;
99	
100	  _Attempt? _attempt;
101	
102	  /// Opening threw (hashing, a missing file); shown instead of the stage.
103	  String? _openError;
104	
105	  /// The last error the player logged for the open copy; fatal only while nothing loaded.
106	  String? _playerError;
107	  final List<StreamSubscription<Object>> _subs = [];
108	
109	  /// Reconnect bookkeeping: RoomClient is one socket, so a drop means a fresh client.
110	  bool _joinedOnce = false;
111	  int _retries = 0;
112	  Timer? _retryTimer;
113	  String? _gaveUp;
114	
115	  PauseNotice? _pause;
116	  int _pauseSerial = 0;
117	  DateTime? _pauseSentAt;
118	
119	  /// Names and durations of copies opened or queued here, so queue rows read as titles.
120	  final Map<String, ({String name, int? durationMs})> _known = {};
121	
122	  bool get _joined => _client.status == ConnectionStatus.joined;
123	
124	  @override
125	  void initState() {
126	    super.initState();
127	    _client = _connect(widget.clientId);
128	    _pollTimer = Timer.periodic(pollEvery, (_) => _poll());
129	    _reportTimer = Timer.periodic(reportEvery, (_) => _report());
130	    final stream = _player.player.stream;
131	    void refresh(Object _) {
132	      if (mounted) setState(() {});
133	    }
134	
135	    _subs.addAll([
136	      stream.error.listen((e) {
137	        if (mounted) setState(() => _playerError = e);
138	      }),
139	      stream.buffering.listen(refresh),
140	      stream.completed.listen(refresh),
141	      stream.tracks.listen(refresh),
142	    ]);
143	    _player.player.setVolume(_volume);
144	    final initial = widget.initialCopy;
145	    if (initial != null) {
146	      initial.isRemote ? _openRemote(initial) : _openPath(initial.path);
147	    }
148	  }
149	
150	  @override
151	  void dispose() {
152	    _pollTimer.cancel();
153	    _reportTimer.cancel();
154	    _retryTimer?.cancel();
155	    for (final s in _subs) {
156	      s.cancel();
157	    }
158	    _client.close();
159	    _player.dispose();
160	    if (_fullscreen) defaultExitNativeFullscreen();
161	    super.dispose();
162	  }
163	
164	  RoomClient _connect(String? clientId) => RoomClient(
165	    server: widget.server,
166	    room: widget.room,
167	    token: widget.token,
168	    name: widget.name,
169	    clientId: clientId,
170	    onMessage: _onMessage,
171	    onChange: _onClientChange,
172	  )..connect();
173	
174	  void _onClientChange() {
175	    // The first completed clock burst makes anchors meaningful: apply the one we hold.
176	    if (_client.clock.ready && !_clockWasReady) {
177	      _clockWasReady = true;
178	      _apply();
179	    }
180	    if (_joined) {
181	      _joinedOnce = true;
182	      _retries = 0;
183	    }
184	    if (_client.status == ConnectionStatus.closed) _scheduleReconnect();
185	    setState(() {});
186	  }
187	
188	  /// Retries with backoff, keeping our client id; a refused token or a gone room is final.
189	  void _scheduleReconnect() {
190	    if (_retryTimer?.isActive ?? false) return;
191	    final reason = _client.closeReason ?? 'connection closed';
192	    if (reason.contains('4001') || reason.contains('4004')) {
193	      _gaveUp = reason;
194	      return;
195	    }
196	    final delay = Duration(seconds: math.min(10, 1 << math.min(_retries, 4)));
197	    _retries++;
198	    _retryTimer = Timer(delay, () {
199	      if (!mounted) return;
200	      final id = _client.clientId;
201	      _client.close();
202	      setState(() {
203	        _clockWasReady = false;
204	        _client = _connect(id);
205	      });
206	    });
207	  }
208	
209	  void _onMessage(Message message) {
210	    switch (message.body) {
211	      case WelcomeMsg(:final snapshot):
212	        setState(() {
213	          _rev = snapshot.rev;
214	          _setAnchor(snapshot.playback);
215	          _queue = snapshot.queue;
216	          _learnTitles();
217	          _meta = snapshot.meta ?? _meta;
218	          _members
219	            ..clear()
220	            ..addAll(snapshot.presence);
221	        });
222	        _apply();
223	      case StateMsg state when state.rev > _rev:
224	        setState(() {
225	          _rev = state.rev;
226	          _setAnchor(state.playback);
227	          _queue = state.queue;
228	          _learnTitles();
229	          _meta = state.meta ?? _meta;
230	        });
231	        _apply();
232	      case PresenceMsg p:
233	        setState(() {
234	          _members.removeWhere((m) => m.userId == p.userId);
235	          if (p.joined) _members.add(Member(userId: p.userId, name: p.name));
236	        });
237	      case RejectMsg(:final message):
238	        ScaffoldMessenger.of(
239	          context,
240	        ).showSnackBar(SnackBar(content: Text(message)));
241	      default:
242	        break;
243	    }
244	  }
245	
246	  /// Queue rows carry the title they were added with; keep it so the item stays named once it
247	  /// leaves the queue and plays (the waiting card names the room's file).
248	  void _learnTitles() {
249	    for (final q in _queue) {
250	      final title = q.title;
251	      if (title != null) {
252	        _known.putIfAbsent(
253	          q.itemRef,
254	          () => (name: title, durationMs: q.durationMs),
255	        );
256	      }
257	    }
258	  }
259	
260	  /// Raises a pause notice on a playing → paused transition; clears it once playback resumes.
261	  void _setAnchor(Playback? next) {
262	    final prev = _anchor;
263	    _anchor = next;
264	    if (next == null || !next.paused) {
265	      _pause = null;
266	      return;
267	    }
268	    if (prev == null || prev.paused) return;
269	    final sent = _pauseSentAt;
270	    final others = _members.where((m) => m.userId != _client.clientId).toList();
271	    final String? by;
272	    if (sent != null && DateTime.now().difference(sent) < ownPauseWindow) {
273	      by = 'You';
274	    } else if (others.length == 1) {
275	      by = others.single.name ?? 'Someone';
276	    } else {
277	      by = null;
278	    }
