                ),
                const SizedBox(height: 10),
                if (now != null) _QueueTile(row: now, now: true),
                if (data.upNext.isNotEmpty) ...[
                  const SizedBox(height: 12),
                  const WtLabel('Up next'),
                  const SizedBox(height: 6),
