    final inSync = sync == SyncState.inSync;
    final color = inSync ? WtColors.cyan : WtColors.yellow;
    final drift = driftMs;
    return Tooltip(
      message: drift == null
          ? (inSync ? 'Matching the room' : 'Catching up with the room')
