          const SizedBox(width: 12),
          Semantics(
            label: '${_d.people.length} in the room',
            excludeSemantics: true,
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                const Icon(
                  Icons.people_alt_rounded,
