      const SizedBox(width: 8),
      _CornerPill(
        label: 'Exit fullscreen',
        icon: Icons.fullscreen_exit_rounded,
        tooltip: 'Exit fullscreen (Esc)',
        onTap: widget.onFullscreen,
      ),
    ],
