          _SkipChip(
            label: '−10s',
            tooltip: tip('Back 10 seconds'),
            onTap: _seek(-skipMs),
          ),
          const SizedBox(width: 10),
          CompositedTransformTarget(
            link: _playLink,
            child: _PlayButton(playing: _d.playing, onTap: _playPause),
          ),
          const SizedBox(width: 10),
          _SkipChip(
            label: '+10s',
            tooltip: tip('Ahead 10 seconds'),
            onTap: _seek(skipMs),
          ),
