/// A quiet glass pill for the fullscreen corner: always readable, low enough in contrast that it
/// does not fight the picture. [on] makes it a toggle.
class _CornerPill extends StatelessWidget {
  const _CornerPill({
    required this.label,
    required this.icon,
    required this.tooltip,
    required this.onTap,
    this.on,
  });
  final String label;
  final IconData icon;
  final String tooltip;
  final VoidCallback? onTap;
  final bool? on;

  @override
  Widget build(BuildContext context) {
    final lit = on ?? false;
    return Semantics(
      toggled: on,
      child: WtTap(
        onTap: onTap,
        radius: 18,
        tooltip: tooltip,
        child: Container(
          height: 36,
          padding: const EdgeInsets.symmetric(horizontal: 12),
          decoration: _glass,
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(icon, size: 17, color: lit ? WtColors.pink : WtColors.tx3),
              const SizedBox(width: 6),
              Text(
                label,
                style: TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w800,
