              const Icon(Icons.check_circle, size: 22, color: WtColors.cyan)
            else
              WtFileGlyph(
                size: 22,
                color: differs ? WtColors.yellow : WtColors.tx3,
              ),
            const SizedBox(width: 10),
            Expanded(
              child: Text.rich(
                TextSpan(
                  children: matches
                      ? [
