);

class _PromptDialog extends StatefulWidget {
  const _PromptDialog({
    required this.title,
    required this.initial,
    required this.hint,
    required this.icon,
    required this.validate,
  });
  final String title;
  final String initial;
  final String hint;
  final IconData icon;
  final String? Function(String?) validate;

  @override
  State<_PromptDialog> createState() => _PromptDialogState();
}

class _PromptDialogState extends State<_PromptDialog> {
  late final _draft = TextEditingController(text: widget.initial);
  String? _error;

  @override
  void dispose() {
    _draft.dispose();
    super.dispose();
  }

  void _save() {
    final problem = widget.validate(_draft.text);
    if (problem != null) {
      setState(() => _error = problem);
    } else {
      Navigator.of(context).pop(_draft.text.trim());
    }
  }

  @override
  Widget build(BuildContext context) => Dialog(
    backgroundColor: WtColors.plum2,
    shape: RoundedRectangleBorder(
      borderRadius: BorderRadius.circular(WtRadius.surface),
      side: const BorderSide(color: WtColors.line, width: 2),
    ),
    child: SizedBox(
      width: 440,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(24, 20, 24, 20),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Expanded(
                  child: Text(
                    widget.title,
                    style: Theme.of(context).textTheme.titleLarge,
                  ),
                ),
                WtIconButton(
                  icon: Icons.close_rounded,
                  tooltip: 'Close',
                  onPressed: () => Navigator.of(context).pop(),
                ),
              ],
            ),
            const SizedBox(height: 16),
            WtField(
              controller: _draft,
              hint: widget.hint,
              icon: widget.icon,
              autofocus: true,
              height: 56,
              onChanged: (_) => setState(() => _error = null),
              onSubmitted: (_) => _save(),
            ),
            if (_error != null) ...[
              const SizedBox(height: 8),
              Text(
                _error!,
                style: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w700,
                  color: WtColors.yellow,
                ),
              ),
            ],
            const SizedBox(height: 20),
            Align(
              alignment: Alignment.centerRight,
              child: WtButton(label: 'Save', onPressed: _save),
            ),
          ],
        ),
      ),
    ),
  );
