String? validateServerUrl(String? value) {
  final uri = Uri.tryParse((value ?? '').trim());
  return uri != null &&
          (uri.scheme == 'http' || uri.scheme == 'https') &&
          uri.host.isNotEmpty
      ? null
      : 'Enter an http:// or https:// server URL';
}

/// Where the pasted invite stands after parsing and `GET /rooms/{id}`.
enum InviteState {
  empty,
  malformed,
  checking,
  found,
  unchecked,
  expired,
  ended,
}

class HomeScreen extends StatefulWidget {
  const HomeScreen({
    super.key,
    this.api = const HttpRoomApi(),
    this.pickCopy = pickLocalCopy,
    this.jellyfin = const HttpJellyfinApi(),
    this.initialInvite,
    this.forwardedInvites,
  });
  final RoomApi api;
  final PickCopy pickCopy;
  final JellyfinApi jellyfin;

  /// Invite URL the app was launched with, if any.
  final String? initialInvite;

  /// Invites that arrived from a second launch while this window was already open.
  final Stream<String>? forwardedInvites;

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  final _invite = TextEditingController();
  String _server = defaultServerUrl;
  String _name = Platform.localHostname == 'localhost'
      ? 'You'
      : Platform.localHostname;
  int? _rtt;
  bool _offline = false;
  InviteLink? _link;
  InviteState _state = InviteState.empty;
  RoomInfo? _info;
  int _lookupSeq = 0;
  LocalCopy? _copy;
  bool _creating = false;
  String? _createError;

  late final _local = LocalMediaSource(pickFile: widget.pickCopy);

  /// Restored from the saved config at startup; the library's `Connect Jellyfin` signs in.
  late final _jellyfin = JellyfinMediaSource(
    api: widget.jellyfin,
    signIn: (previous) =>
        showJellyfinSignIn(context, api: widget.jellyfin, previous: previous),
  );

  /// Shared with the room, so a sign-in or a file opened here is still there after joining.
  late final _sources = mediaSources(local: _local, jellyfin: _jellyfin);

  Uri get _serverUri => Uri.parse(_server);

  @override
  void initState() {
    super.initState();
    unawaited(_ping());
    unawaited(_jellyfin.restore());
    final invite = widget.initialInvite;
    if (invite != null && invite.isNotEmpty) {
      _invite.text = invite;
      _onInvite(invite);
    }
    _forwarded = widget.forwardedInvites?.listen(_takeForwarded);
  }

  StreamSubscription<String>? _forwarded;

  /// A later launch handed us an invite: show it without losing the room we are already in.
  void _takeForwarded(String text) {
    final link = parseInviteLink(text);
    if (link == null || !mounted) return;
    _invite.text = text;
    _onInvite(text);
  }

  @override
  void dispose() {
    unawaited(_forwarded?.cancel());
    _invite.dispose();
    super.dispose();
  }

  Future<void> _ping() async {
    setState(() {
      _rtt = null;
      _offline = false;
    });
    final server = _server;
    try {
      final rtt = await widget.api.ping(_serverUri);
      if (mounted && server == _server) setState(() => _rtt = rtt);
    } on Object {
      if (mounted && server == _server) setState(() => _offline = true);
    }
  }

  void _onInvite(String text) {
    final link = parseInviteLink(text);
    final seq = ++_lookupSeq;
    setState(() {
      _link = link;
      _info = null;
      _state = text.trim().isEmpty
          ? InviteState.empty
          : link == null
          ? InviteState.malformed
          : InviteState.checking;
    });
    if (link != null) unawaited(_lookup(link, seq));
  }

  Future<void> _lookup(InviteLink link, int seq) async {
    InviteState state;
    RoomInfo? info;
    try {
      info = await widget.api.lookup(_serverUri, link.room);
      final exp = tokenExpiryMs(link.token);
      state = info == null
          ? InviteState.ended
          : exp != null && exp <= DateTime.now().millisecondsSinceEpoch
          ? InviteState.expired
          : InviteState.found;
    } on Object {
      // Fail open: the code is still shown and joining stays possible.
      state = InviteState.unchecked;
    }
    if (!mounted || seq != _lookupSeq) return;
    setState(() {
      _state = state;
      _info = info;
    });
  }

  Future<void> _paste() async {
    final data = await Clipboard.getData(Clipboard.kTextPlain);
    final text = data?.text?.trim();
    if (text == null || text.isEmpty || !mounted) return;
    _invite.text = text;
    _onInvite(text);
  }

  /// The library; what is played there becomes the copy to join with. [initial] opens on that
  /// source's tab.
  Future<void> _pickMedia({MediaSourceKind? initial}) async {
    final copy = await showMediaLibrary(
      context,
      sources: _sources,
      initial: initial,
    );
    if (copy != null && mounted) setState(() => _copy = copy);
  }

  bool get _linkUsable =>
      _link != null &&
      (_state == InviteState.found ||
          _state == InviteState.unchecked ||
          _state == InviteState.checking);

  bool get _canJoin =>
      _copy != null &&
      _link != null &&
      (_state == InviteState.found || _state == InviteState.unchecked);

  void _join() {
    if (!_canJoin) return;
    _enter(_link!, copy: _copy);
  }

  void _enter(InviteLink link, {String? hostId, LocalCopy? copy}) {
    Navigator.of(context).push(
      wtRoute(
        RoomScreen(
          server: _serverUri,
          room: link.room,
          token: link.token,
          name: _name,
          clientId: hostId,
          initialCopy: copy,
          sources: _sources,
        ),
      ),
    );
  }

  Future<void> _createRoom() async {
    setState(() {
      _creating = true;
      _createError = null;
    });
    try {
      final created = await widget.api.create(_serverUri);
      if (!mounted) return;
      setState(() => _creating = false);
      final enter = await showRoomReady(
        context,
        server: _serverUri,
        created: created,
        name: _name,
        copy: _copy,
        api: widget.api,
        pickCopy: widget.pickCopy,
        onCopy: (copy) {
          _local.remember(copy);
          setState(() => _copy = copy);
        },
      );
      if (enter == true && mounted) {
        _enter(
          (room: created.room, token: created.token),
          hostId: created.hostId,
          copy: _copy,
        );
      }
    } on Object catch (e) {
      if (mounted) setState(() => _createError = '$e');
    } finally {
      if (mounted && _creating) setState(() => _creating = false);
    }
  }

  void _askForNewLink() {
    final host = _info?.hostName;
    final code = _link?.room ?? '';
    Clipboard.setData(
      ClipboardData(
        text:
            'My watch·together invite for room $code expired — '
            'could you send a fresh link?',
      ),
    );
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          host == null
              ? 'Message copied — paste it to whoever invited you'
              : 'Message copied — paste it to $host',
        ),
      ),
    );
  }

  Future<void> _changeServer() async {
    final value = await promptText(
      context,
      title: 'Server',
      initial: _server,
      hint: 'https://…',
      icon: Icons.dns_outlined,
      validate: validateServerUrl,
    );
    if (value == null || !mounted) return;
    setState(() => _server = value);
    unawaited(_ping());
    if (_link != null) _onInvite(_invite.text);
  }

  Future<void> _changeName() async {
    final value = await promptText(
      context,
      title: 'Your name',
      initial: _name,
      hint: 'What friends call you',
      icon: Icons.person_outline,
      validate: (v) =>
          (v ?? '').trim().isEmpty ? 'Enter a name others will see' : null,
    );
    if (value != null && mounted) setState(() => _name = value);
  }

  int get _nextStep => !_linkUsable
      ? 0
      : _copy == null
      ? 1
      : 2;

  @override
  Widget build(BuildContext context) => WtScaffold(
    child: Focus(
      autofocus: true,
      onKeyEvent: _onKey,
      child: WtBackdrop(
        child: LayoutBuilder(
          builder: (context, box) {
            final inner = box.maxWidth - 2 * WtSpace.window;
            final gap = ((inner - 320 - 504) / 3).clamp(48.0, 144.0);
            final brandHeight = (box.maxHeight - 2 * WtSpace.window).clamp(
              0.0,
              640.0,
            );
            final compact = box.maxWidth < wtCompactWidth;
            return SingleChildScrollView(
              padding: const EdgeInsets.all(WtSpace.window),
              child: ConstrainedBox(
                constraints: BoxConstraints(
                  minHeight: box.maxHeight - 2 * WtSpace.window,
                ),
                child: Center(
                  child: compact
                      ? Column(
                          mainAxisSize: MainAxisSize.min,
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          children: [
                            _Brand(
                              next: _nextStep,
                              status: _statusRow(),
                              compact: true,
                            ),
                            const SizedBox(height: 32),
                            _card(),
                          ],
                        )
                      : Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            SizedBox(
                              width: 320,
                              height: brandHeight,
                              child: _Brand(
                                next: _nextStep,
                                status: _statusRow(),
                              ),
                            ),
                            SizedBox(width: gap),
                            SizedBox(width: 504, child: _card()),
                          ],
                        ),
                ),
              ),
            );
          },
        ),
      ),
    ),
  );

  /// Ctrl+V anywhere on Home pastes the invite, unless a text field already has focus.
  KeyEventResult _onKey(FocusNode node, KeyEvent event) {
    if (event is! KeyDownEvent ||
        event.logicalKey != LogicalKeyboardKey.keyV ||
        !HardwareKeyboard.instance.isControlPressed) {
      return KeyEventResult.ignored;
    }
    final focused = FocusManager.instance.primaryFocus?.context;
    if (focused?.findAncestorWidgetOfExactType<EditableText>() != null) {
      return KeyEventResult.ignored;
    }
    unawaited(_paste());
    return KeyEventResult.handled;
  }

  Widget _statusRow() {
    final host = _serverUri.host;
    final (color, style, text) = _offline
        ? (WtColors.yellow, WtDotStyle.ring, "Can't reach $host")
        : _rtt == null
        ? (WtColors.tx3, WtDotStyle.ring, 'Connecting to $host…')
        : (WtColors.cyan, WtDotStyle.solid, 'Connected to $host · $_rtt ms');
    return Row(
      children: [
        WtDot(color: color, style: style),
        const SizedBox(width: 10),
        Flexible(
          child: Tooltip(
            message: _server,
            child: Text(
              text,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                fontSize: 13,
                fontWeight: FontWeight.w700,
                color: WtColors.tx3,
              ),
            ),
          ),
        ),
        const SizedBox(width: 8),
        _GhostChip(
          label: 'Change server',
          icon: Icons.dns_outlined,
          onTap: _changeServer,
        ),
      ],
    );
  }

  Widget _card() => Container(
    key: homeCardKey,
    padding: const EdgeInsets.fromLTRB(24, 24, 24, 20),
    decoration: BoxDecoration(
      color: WtColors.s1,
      borderRadius: BorderRadius.circular(28),
      border: Border.all(color: WtColors.line, width: 2),
      boxShadow: const [
        BoxShadow(color: Color(0x08FFFFFF), spreadRadius: 8),
        BoxShadow(
          color: Color(0x99000000),
          offset: Offset(0, 30),
          blurRadius: 60,
          spreadRadius: -20,
        ),
      ],
    ),
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        Row(
          children: [
            Expanded(
              child: Text(
                'Join a room',
                style: Theme.of(context).textTheme.headlineMedium,
              ),
            ),
            _NameChip(name: _name, onTap: _changeName),
          ],
        ),
        const SizedBox(height: 18),
        WtLabel(
          'Invite link',
          trailing: const Padding(
            padding: EdgeInsets.only(right: 12),
            child: Text(
              'Ctrl V to paste',
              style: TextStyle(
                fontSize: 12,
                fontWeight: FontWeight.w700,
                color: WtColors.tx3,
              ),
            ),
          ),
        ),
        const SizedBox(height: 8),
        WtField(
          controller: _invite,
          hint: 'Paste the invite link',
          icon: Icons.link,
          onChanged: _onInvite,
          onSubmitted: (_) => _join(),
          trailing: WtIconButton(
            icon: Icons.content_paste_rounded,
            tooltip: 'Paste',
            onPressed: _paste,
          ),
        ),
        const SizedBox(height: 12),
        ..._inviteBody(),
        const SizedBox(height: 16),
        _cta(),
        const SizedBox(height: 18),
        const Divider(height: 2, thickness: 2, color: WtColors.line),
        const SizedBox(height: 16),
        Row(
          children: [
            WtButton(
              label: _creating ? 'Starting…' : 'Start a room',
              icon: Icons.add,
              style: WtButtonStyle.ghost,
              size: WtButtonSize.small,
              onPressed: _creating ? null : _createRoom,
            ),
            const SizedBox(width: 14),
            const Expanded(
              child: Text(
                'Host and send your own link.',
                maxLines: 2,
                style: TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w600,
                  color: WtColors.tx3,
                ),
              ),
            ),
          ],
        ),
        if (_createError != null) ...[
          const SizedBox(height: 10),
          _CalmLine(
            icon: Icons.cloud_off_outlined,
            text: "Couldn't start a room: $_createError",
          ),
        ],
      ],
    ),
  );

  List<Widget> _inviteBody() {
    final link = _link;
    switch (_state) {
      case InviteState.empty:
        return const [
          _CalmLine(
            icon: Icons.info_outline,
            text:
                'Paste the whole message from Discord. '
                'The link already knows the server.',
          ),
        ];
      case InviteState.malformed:
        return const [
          _CalmLine(
            icon: Icons.link_off,
            text:
                'That link looks cut off. Invites end in a code like '
                '…/join/eyJy…  — try copying the whole message again.',
          ),
        ];
      case InviteState.expired:
        final info = _info!;
        return [
          WtAlert(
            icon: Icons.schedule,
            title: 'This link expired, but the room is still running',
            body:
                '${info.hostName ?? 'Whoever invited you'} can send a fresh one.',
            actions: [
              Row(
                children: [
                  WtPill(
                    label: 'Live now · ${info.memberCount} inside',
                    tone: WtTone.live,
                    dot: WtDotStyle.pulse,
                    height: 28,
                    fontSize: 13,
                  ),
                  const SizedBox(width: 10),
                  Flexible(
                    child: WtButton(
                      label: 'Ask for a new link',
                      style: WtButtonStyle.ghost,
                      size: WtButtonSize.small,
                      onPressed: _askForNewLink,
                    ),
                  ),
                ],
              ),
            ],
          ),
        ];
      case InviteState.ended:
        return [
          WtAlert(
            icon: Icons.stop_circle_outlined,
            title: 'This room has ended',
            body: 'Start a new one and send your own link.',
            actions: [
              WtButton(
                label: 'Start a room',
                icon: Icons.add,
                style: WtButtonStyle.ghost,
                size: WtButtonSize.small,
                onPressed: _creating ? null : _createRoom,
              ),
            ],
          ),
        ];
      case InviteState.checking || InviteState.found || InviteState.unchecked:
        return [
          _FoundCard(room: link!.room, state: _state, info: _info, copy: _copy),
          if (_copy != null) ...[
            const SizedBox(height: 12),
            _MineRow(
              copy: _copy!,
              hostRef: _info?.itemRef,
              onChange: () => _pickMedia(initial: sourceKindOf(_copy!.itemRef)),
            ),
          ],
        ];
    }
  }

  Widget _cta() {
    final host = _info?.hostName;
    final label = host == null ? 'Join room' : "Join $host's room";
    if (_canJoin) {
      return WtButton(
        label: label,
        trailingIcon: Icons.arrow_forward_rounded,
        size: WtButtonSize.large,
        fullWidth: true,
        onPressed: _join,
      );
    }
    // Shown even with no invite yet: picking what you'll play is the second half of joining, and
    // hiding it until a link is pasted made the Jellyfin picker unfindable.
    final needsCopy = _copy == null;
    final reason = !_linkUsable
        ? 'Paste an invite to join'
        : _state == InviteState.checking
        ? 'Checking the room…'
        : 'Open your copy to join';
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Semantics(
          button: true,
          enabled: false,
          label: '$label, disabled: $reason',
          excludeSemantics: true,
          child: WtDashed(
            color: WtColors.line,
            radius: 20,
            child: Container(
              height: 60,
              decoration: BoxDecoration(
                color: WtColors.s2,
                borderRadius: BorderRadius.circular(20),
              ),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  needsCopy
                      ? const WtFileGlyph(size: 22)
                      : const Icon(Icons.link, size: 22, color: WtColors.tx3),
                  const SizedBox(width: 10),
                  Text(
                    reason,
                    style: const TextStyle(
                      fontSize: 16,
                      fontWeight: FontWeight.w800,
                      color: WtColors.tx3,
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
        if (needsCopy) ...[
          const SizedBox(height: 6),
          Row(
            children: [
              Expanded(
                child: Text(
                  !_linkUsable
                      ? 'Or bring your own copy first.'
                      : host == null
                      ? 'Pick the same file everyone else has.'
                      : '$host is playing their copy. Pick the same file.',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w600,
                    color: WtColors.tx3,
                  ),
                ),
              ),
              WtTextButton(
                label: 'Pick media',
                icon: Icons.video_library_outlined,
                compact: true,
                onPressed: _pickMedia,
              ),
              const SizedBox(width: 4),
            ],
          ),
        ],
      ],
    );
  }
}

class _Brand extends StatelessWidget {
  const _Brand({
    required this.next,
    required this.status,
    this.compact = false,
  });

  /// Index of the step to do next; 0 paste, 1 open copy, 2 play.
  final int next;
  final Widget status;

  /// Narrow window: sized to content, steps folded behind `How it works`.
  final bool compact;

  @override
  Widget build(BuildContext context) {
    final display = Theme.of(context).textTheme.displayLarge;
    _StepState state(int i) => i < next
        ? _StepState.done
        : i == next
        ? _StepState.next
        : _StepState.todo;
    const mark = Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [WtWordmark(), SizedBox(width: 6), WtSpark()],
    );
    final headline = Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text('One screen.', style: display),
        WtGradientText('Same moment.', style: display),
        const SizedBox(height: 16),
        const Text(
          'Everyone plays their own copy, in step. '
          'It plays from your disk — this app only keeps time.',
          style: TextStyle(
            fontSize: 15,
            height: 1.5,
            fontWeight: FontWeight.w500,
            color: WtColors.tx3,
          ),
        ),
      ],
    );
    final steps = Column(
      children: [
        _Step(
          n: 1,
          title: 'Paste the invite',
          body:
              'The link from Discord or a friend. It already knows the server.',
          state: state(0),
        ),
        _Step(
          n: 2,
          title: 'Open your copy',
          body: 'The same file, from your own disk. We check it matches.',
          state: state(1),
        ),
        _Step(
          n: 3,
          title: 'Press play',
          body: 'Anyone can pause or skip. Everyone follows.',
          state: state(2),
          last: true,
        ),
      ],
    );
    if (compact) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisSize: MainAxisSize.min,
        children: [
          mark,
          const SizedBox(height: 24),
          headline,
          const SizedBox(height: 16),
          _Disclosure(label: 'How it works', child: steps),
          const SizedBox(height: 16),
          status,
        ],
      );
    }
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      children: [mark, headline, steps, status],
    );
  }
}

/// A ghost chip that shows or hides [child] below it.
class _Disclosure extends StatefulWidget {
  const _Disclosure({required this.label, required this.child});
  final String label;
  final Widget child;

  @override
  State<_Disclosure> createState() => _DisclosureState();
}

class _DisclosureState extends State<_Disclosure> {
  bool _open = false;

  @override
  Widget build(BuildContext context) => Column(
    crossAxisAlignment: CrossAxisAlignment.start,
    mainAxisSize: MainAxisSize.min,
    children: [
      Semantics(
        expanded: _open,
        child: _GhostChip(
          label: widget.label,
          icon: _open ? Icons.expand_less_rounded : Icons.expand_more_rounded,
          onTap: () => setState(() => _open = !_open),
        ),
      ),
      AnimatedSize(
        duration: const Duration(milliseconds: 200),
        curve: Curves.easeOutCubic,
        alignment: Alignment.topLeft,
        child: _open
            ? Padding(
                padding: const EdgeInsets.only(top: 16),
                child: widget.child,
              )
            : const SizedBox(width: double.infinity),
      ),
    ],
  );
}

/// A small secondary control: plum chip, 2px line border, pill radius.
