1	/// What the library browses. Every item is carried by the `item_ref` the room already speaks, so a
2	/// new source is one more [MediaSource] in [mediaSources] and nothing on the wire changes.
3	library;
4	
5	import 'package:flutter/material.dart';
6	
7	import 'format.dart';
8	import 'jellyfin.dart';
9	import 'local_copy.dart';
10	
11	/// `live` is a stream or URL with no fixed end.
12	enum MediaKind { video, audio, live }
13	
14	enum MediaSourceKind { local, jellyfin, youtube, ytm }
15	
16	/// Read off the ref alone, so a queue row's source always matches what will open.
17	MediaSourceKind sourceKindOf(String ref) => ref.startsWith('jellyfin:')
18	    ? MediaSourceKind.jellyfin
19	    : MediaSourceKind.local;
20	
21	class MediaItem {
22	  const MediaItem({
23	    required this.ref,
24	    required this.title,
25	    required this.kind,
26	    required this.source,
27	    this.subtitle,
28	    this.duration,
29	    this.posterUrl,
30	    this.aspect,
31	  });
32	
33	  /// The `item_ref` that goes on the wire, unchanged.
34	  final String ref;
35	  final String title;
36	
37	  /// Artist/album, show/season, channel; a local file's size.
38	  final String? subtitle;
39	  final MediaKind kind;
40	  final MediaSourceKind source;
41	  final Duration? duration;
42	
43	  /// http(s) art; null for local files.
44	  final String? posterUrl;
45	
46	  /// Width over height of the art: 2/3 for posters, 1 for album art; null when there is none.
47	  final double? aspect;
48	}
49	
50	/// Case-insensitive match on title and subtitle; an empty query matches everything.
51	bool mediaMatches(MediaItem item, String query) {
52	  final q = query.trim().toLowerCase();
53	  return q.isEmpty ||
54	      item.title.toLowerCase().contains(q) ||
55	      (item.subtitle?.toLowerCase().contains(q) ?? false);
56	}
57	
58	/// Something a source offers besides browsing: `Choose file…`, `Change` account.
59	class MediaSourceAction {
60	  const MediaSourceAction({
61	    required this.label,
62	    required this.icon,
63	    required this.run,
64	  });
65	  final String label;
66	  final IconData icon;
67	
68	  /// Resolves to an item to play or queue straight away, or null when there is nothing to pick.
69	  final Future<MediaItem?> Function() run;
70	}
71	
72	abstract class MediaSource {
73	  const MediaSource();
74	
75	  MediaSourceKind get kind;
76	
77	  /// Tab label: `This computer`, `Jellyfin`, `YouTube`.
78	  String get label;
79	
80	  /// Signed in / available. False shows the connect state instead of a grid.
81	  bool get ready;
82	
83	  Future<List<MediaItem>> browse({String query = ''});
84	
85	  /// The sign-in flow, if any.
86	  Future<void> ensureReady();
87	
88	  /// False lists the source with a `Soon` tag and never selects it.
89	  bool get available => true;
90	
91	  /// Who the source is signed in as, for the library header.
92	  String? get account => null;
93	
94	  /// The second line of `Nothing in this library yet`.
95	  String get emptyHint => 'Nothing to show from ${label.toLowerCase()} yet.';
96	
97	  List<MediaSourceAction> get actions => const [];
98	
99	  /// The playable copy behind an item from [browse]; null when it can no longer be opened.
100	  Future<LocalCopy?> open(MediaItem item);
101	}
102	
103	/// The library's tabs, in order. A new adapter is one more entry here.
104	List<MediaSource> mediaSources({
105	  required LocalMediaSource local,
106	  required JellyfinMediaSource jellyfin,
107	}) => [
108	  local,
109	  jellyfin,
110	  const SoonMediaSource(MediaSourceKind.youtube, 'YouTube'),
111	  const SoonMediaSource(MediaSourceKind.ytm, 'Music'),
112	];
113	
114	const Set<String> _audioExtensions = {
115	  'aac',
116	  'aiff',
117	  'alac',
118	  'flac',
119	  'm4a',
120	  'mp3',
121	  'oga',
122	  'ogg',
123	  'opus',
124	  'wav',
125	  'wma',
126	};
127	
128	/// Audio by extension, video otherwise: a picked `.flac` must not be badged as a film.
129	MediaKind mediaKindForPath(String path) {
130	  final dot = path.lastIndexOf('.');
131	  final ext = dot < 0 ? '' : path.substring(dot + 1).toLowerCase();
132	  return _audioExtensions.contains(ext) ? MediaKind.audio : MediaKind.video;
133	}
134	
135	/// Files on this computer. There is no folder to scan: the list is what was opened this session,
136	/// and `Choose file…` is the OS dialog.
137	class LocalMediaSource extends MediaSource {
138	  LocalMediaSource({this.pickFile = pickLocalCopy});
139	
140	  /// Asks for a file, hashes and probes it.
141	  final PickCopy pickFile;
142	  final List<LocalCopy> _recent = [];
143	
144	  @override
145	  MediaSourceKind get kind => MediaSourceKind.local;
146	
147	  @override
148	  String get label => 'This computer';
149	
150	  @override
151	  bool get ready => true;
152	
153	  @override
154	  String get emptyHint =>
155	      'Files you open show up here. There is no folder to scan: pick one.';
156	
157	  @override
158	  Future<void> ensureReady() async {}
159	
160	  /// Puts [copy] first; remote copies belong to their own source.
161	  void remember(LocalCopy copy) {
162	    if (copy.isRemote) return;
163	    _recent
164	      ..removeWhere((c) => c.itemRef == copy.itemRef)
165	      ..insert(0, copy);
166	  }
167	
168	  /// The OS dialog; a picked file is remembered here.
169	  Future<LocalCopy?> pick() async {
170	    final copy = await pickFile();
171	    if (copy != null) remember(copy);
172	    return copy;
173	  }
174	
175	  static MediaItem itemFor(LocalCopy copy) => MediaItem(
176	    ref: copy.itemRef,
177	    title: copy.name,
178	    subtitle: fmtBytes(copy.bytes),
179	    kind: mediaKindForPath(copy.path),
180	    source: MediaSourceKind.local,
181	    duration: copy.duration,
182	  );
183	
184	  @override
185	  Future<List<MediaItem>> browse({String query = ''}) async => [
186	    for (final copy in _recent)
187	      if (itemFor(copy) case final item when mediaMatches(item, query)) item,
188	  ];
189	
190	  @override
191	  List<MediaSourceAction> get actions => [
192	    MediaSourceAction(
193	      label: 'Choose file…',
194	      icon: Icons.folder_open_rounded,
195	      run: () async {
196	        final copy = await pick();
197	        return copy == null ? null : itemFor(copy);
198	      },
199	    ),
200	  ];
201	
202	  @override
203	  Future<LocalCopy?> open(MediaItem item) async {
204	    for (final copy in _recent) {
205	      if (copy.itemRef == item.ref) return copy;
206	    }
207	    return null;
208	  }
209	}
210	
211	/// Movies on the viewer's own Jellyfin. Each viewer streams with their own token; the room only
212	/// sees `jellyfin:<host>/<itemId>`.
213	class JellyfinMediaSource extends MediaSource {
214	  JellyfinMediaSource({required this.api, required this.signIn});
215	
216	  final JellyfinApi api;
217	
218	  /// The sign-in form, pre-filled from [previous]; resolves to the new session, or null when closed.
219	  final Future<JellyfinSession?> Function(JellyfinSession? previous) signIn;
220	
221	  JellyfinSession? _session;
222	
223	  /// Kept after the session is dropped, so the form opens on the same server and user.
224	  JellyfinSession? _previous;
225	  List<JellyfinItem>? _movies;
226	  bool _restored = false;
227	
228	  JellyfinSession? get session => _session;
229	
230	  @override
231	  MediaSourceKind get kind => MediaSourceKind.jellyfin;
232	
233	  @override
234	  String get label => 'Jellyfin';
235	
236	  @override
237	  bool get ready => _session != null;
238	
239	  @override
240	  String get emptyHint => 'Movies added to your Jellyfin server show up here.';
241	
242	  @override
243	  String? get account => switch (_session) {
244	    final s? => 'Signed in as ${s.user} on ${s.server.host}',
245	    null => null,
246	  };
247	
248	  /// Picks up the sign-in saved on this machine, once.
249	  Future<void> restore() async {
250	    if (_restored) return;
251	    _restored = true;
252	    try {
253	      final saved = await api.restore();
254	      if (_session == null && saved != null) _use(saved);
255	    } on Object {
256	      // Nothing saved that parses; the library offers to connect.
257	    }
258	  }
259	
260	  void _use(JellyfinSession session) {
261	    _session = _previous = session;
262	    _movies = null;
263	  }
264	
265	  @override
266	  Future<void> ensureReady() async {
267	    await restore();
268	    if (_session != null) return;
269	    final session = await signIn(_previous);
270	    if (session != null) _use(session);
271	  }
272	
273	  @override
274	  List<MediaSourceAction> get actions => [
275	    if (_session != null)
276	      MediaSourceAction(
277	        label: 'Change',
278	        icon: Icons.swap_horiz_rounded,
279	        run: () async {
280	          final session = await signIn(_session);
281	          if (session != null) _use(session);
282	          return null;
283	        },
284	      ),
285	  ];
286	
287	  static MediaItem itemFor(JellyfinSession session, JellyfinItem movie) =>
288	      MediaItem(
289	        ref: jellyfinRef(session.server, movie.id),
290	        title: movie.name,
291	        kind: MediaKind.video,
292	        source: MediaSourceKind.jellyfin,
293	        duration: movie.runtime,
294	        posterUrl: posterUrl(
295	          server: '${session.server}',
296	          token: session.token,
297	          itemId: movie.id,
298	        ),
299	        aspect: 2 / 3,
300	      );
301	
302	  /// An unfiltered browse fetches afresh; typing filters what was fetched.
303	  @override
304	  Future<List<MediaItem>> browse({String query = ''}) async {
305	    final session = _session;
306	    if (session == null) return const [];
307	    try {
308	      final movies = query.trim().isEmpty || _movies == null
309	          ? _movies = await session.movies()
310	          : _movies!;
311	      return [
312	        for (final movie in movies)
313	          if (itemFor(session, movie) case final item
314	              when mediaMatches(item, query))
315	            item,
316	      ];
317	    } on JellyfinException catch (e) {
318	      // A saved token can be revoked: drop it so the library asks to connect again.
319	      if (e.status == 401 && identical(_session, session)) _session = null;
320	      rethrow;
321	    }
322	  }
323	
324	  @override
325	  Future<LocalCopy?> open(MediaItem item) async {
326	    final session = _session;
327	    final parts = parseJellyfinRef(item.ref);
328	    if (session == null || parts == null) return null;
329	    return LocalCopy.remote(
330	      url: streamUrl(
331	        server: '${session.server}',
332	        token: session.token,
333	        itemId: parts.itemId,
334	      ),
335	      itemRef: item.ref,
336	      title: item.title,
337	      duration: item.duration,
338	    );
339	  }
340	}
341	
342	/// Planned, not built: listed with a `Soon` tag so the shape is visible, never browsed.
343	class SoonMediaSource extends MediaSource {
344	  const SoonMediaSource(this.kind, this.label);
345	
346	  @override
347	  final MediaSourceKind kind;
348	
349	  @override
350	  final String label;
351	
352	  @override
353	  bool get ready => false;
354	
355	  @override
356	  bool get available => false;
357	
358	  @override
359	  Future<List<MediaItem>> browse({String query = ''}) async => const [];
360	
361	  @override
362	  Future<void> ensureReady() async {}
363	
364	  @override
365	  Future<LocalCopy?> open(MediaItem item) async => null;
366	}
