1	/// The library: one full-height surface for picking what to play or queue. Tabs, cards and empty
2	/// states are built from the registered [MediaSource]s, so a new source is a new tab and nothing
3	/// here changes.
4	library;
5	
6	import 'dart:async';
7	import 'dart:math' as math;
8	
9	import 'package:flutter/material.dart';
10	import 'package:flutter/services.dart';
11	
12	import 'format.dart';
13	import 'local_copy.dart';
14	import 'media.dart';
15	import 'theme.dart';
16	import 'widgets/button.dart';
17	import 'widgets/chrome.dart';
18	import 'widgets/field.dart';
19	
20	/// `play` closes on the first pick with that item's copy; `queue` hands every pick to `onQueue` and
21	/// stays open so several can be added.
22	enum LibraryMode { play, queue }
23	
24	/// Art for a poster URL; tests swap in memory images.
25	typedef PosterImage = ImageProvider Function(String url);
26	
27	ImageProvider networkPoster(String url) => NetworkImage(url);
28	
29	/// Resolves to the picked item's copy in [LibraryMode.play]; null when closed, and always null in
30	/// [LibraryMode.queue].
31	Future<LocalCopy?> showMediaLibrary(
32	  BuildContext context, {
33	  required List<MediaSource> sources,
34	  LibraryMode mode = LibraryMode.play,
35	  MediaSourceKind? initial,
36	  ValueChanged<MediaItem>? onQueue,
37	  PosterImage poster = networkPoster,
38	}) => Navigator.of(context).push<LocalCopy>(
39	  wtRoute(
40	    MediaLibrary(
41	      sources: sources,
42	      mode: mode,
43	      initial: initial,
44	      onQueue: onQueue,
45	      poster: poster,
46	    ),
47	  ),
48	);
49	
50	class MediaLibrary extends StatefulWidget {
51	  const MediaLibrary({
52	    super.key,
53	    required this.sources,
54	    this.mode = LibraryMode.play,
55	    this.initial,
56	    this.onQueue,
57	    this.poster = networkPoster,
58	  }) : assert(mode == LibraryMode.play || onQueue != null);
59	
60	  /// The tabs, in order.
61	  final List<MediaSource> sources;
62	  final LibraryMode mode;
63	
64	  /// The tab to open on; the first available source when null or not available.
65	  final MediaSourceKind? initial;
66	
67	  /// Adds an item to the room's queue. In play mode a non-null value puts `Queue` beside `Play`.
68	  final ValueChanged<MediaItem>? onQueue;
69	  final PosterImage poster;
70	
71	  @override
72	  State<MediaLibrary> createState() => _MediaLibraryState();
73	}
74	
75	class _MediaLibraryState extends State<MediaLibrary> {
76	  final _query = TextEditingController();
77	  final _search = FocusNode(debugLabel: 'library search');
78	  final _keys = FocusNode(debugLabel: 'library');
79	  final _scroll = ScrollController();
80	  late int _tab = _initialTab();
81	
82	  /// Null while the tab loads.
83	  List<MediaItem>? _items;
84	  Object? _error;
85	  int _seq = 0;
86	  int? _selected;
87	
88	  /// The ref being opened, or the label of the action running; other actions wait for it.
89	  String? _busy;
90	  final Set<String> _queued = {};
91	  int _columns = 1;
92	  double _rowExtent = 0;
93	
94	  static const _connecting = 'connect';
95	  static const _muted = TextStyle(
96	    fontSize: 14,
97	    height: 1.45,
98	    fontWeight: FontWeight.w600,
99	    color: WtColors.tx3,
100	  );
101	
102	  bool get _queueMode => widget.mode == LibraryMode.queue;
103	  MediaSource get _source => widget.sources[_tab];
104	
105	  /// `Nothing in this library yet`: the empty state carries the source's actions, so the toolbar
106	  /// leaves them out.
107	  bool get _emptyLibrary =>
108	      _source.ready &&
109	      _error == null &&
110	      (_items?.isEmpty ?? false) &&
111	      _query.text.trim().isEmpty;
112	
113	  int _initialTab() {
114	    final sources = widget.sources;
115	    final wanted = sources.indexWhere(
116	      (s) => s.kind == widget.initial && s.available,
117	    );
118	    if (wanted >= 0) return wanted;
119	    return math.max(0, sources.indexWhere((s) => s.available));
120	  }
121	
122	  @override
123	  void initState() {
124	    super.initState();
125	    unawaited(_fetch());
126	  }
127	
128	  @override
129	  void dispose() {
130	    _query.dispose();
131	    _search.dispose();
132	    _keys.dispose();
133	    _scroll.dispose();
134	    super.dispose();
135	  }
136	
137	  /// [fresh] blanks the grid while it loads (a tab switch); a search keeps the old cards up until
138	  /// the new ones arrive.
139	  void _reload({bool fresh = true}) {
140	    setState(() {
141	      if (fresh) _items = null;
142	      _error = null;
143	      _selected = null;
144	    });
145	    unawaited(_fetch());
146	  }
147	
148	  Future<void> _fetch() async {
149	    final source = _source;
150	    final seq = ++_seq;
151	    try {
152	      final items = source.available && source.ready
153	          ? await source.browse(query: _query.text)
154	          : const <MediaItem>[];
155	      if (mounted && seq == _seq) setState(() => _items = items);
156	    } on Object catch (e) {
157	      if (mounted && seq == _seq) {
158	        setState(() {
159	          _items = const [];
160	          _error = e;
161	        });
162	      }
163	    }
164	  }
165	
166	  void _pickTab(int i) {
167	    if (i == _tab || !widget.sources[i].available) return;
168	    _tab = i;
169	    _reload();
170	  }
171	
172	  void _say(String message) =>
173	      ScaffoldMessenger.of(context)
174	          .showSnackBar(SnackBar(content: Text(message)));
175	
176	  Future<void> _connect() async {
177	    final source = _source;
178	    setState(() => _busy = _connecting);
179	    try {
180	      await source.ensureReady();
181	    } on Object catch (e) {
182	      if (mounted) _say("Couldn't connect ${source.label}: $e");
183	    } finally {
184	      if (mounted) setState(() => _busy = null);
185	    }
186	    if (mounted && identical(source, _source)) _reload();
187	  }
188	
189	  Future<void> _run(MediaSourceAction action) async {
190	    setState(() => _busy = action.label);
191	    MediaItem? item;
192	    try {
193	      item = await action.run();
194	    } on Object catch (e) {
195	      if (mounted) _say("Couldn't open that: $e");
196	    } finally {
197	      if (mounted) setState(() => _busy = null);
198	    }
199	    if (!mounted) return;
200	    _reload(fresh: false);
201	    if (item != null) await _primary(item);
202	  }
203	
204	  /// `Play` or `Queue this`, whichever the mode makes the main action.
205	  Future<void> _primary(MediaItem item) async {
206	    if (_queueMode) {
207	      _queue(item);
208	    } else {
209	      await _play(item);
210	    }
211	  }
212	
213	  void _queue(MediaItem item) {
214	    widget.onQueue!(item);
215	    setState(() => _queued.add(item.ref));
216	  }
217	
218	  Future<void> _play(MediaItem item) async {
219	    final source = widget.sources.firstWhere((s) => s.kind == item.source);
220	    setState(() => _busy = item.ref);
221	    try {
222	      final copy = await source.open(item);
223	      if (!mounted) return;
224	      if (copy == null) {
225	        _say("Couldn't open ${item.title} any more. Pick it again.");
226	        return;
227	      }
228	      Navigator.of(context).pop(copy);
229	    } on Object catch (e) {
230	      if (mounted) _say("Couldn't open ${item.title}: $e");
231	    } finally {
232	      if (mounted) setState(() => _busy = null);
233	    }
234	  }
235	
236	  void _select(int i) {
237	    setState(() => _selected = i);
238	    if (!_scroll.hasClients || _rowExtent <= 0) return;
239	    final pos = _scroll.position;
240	    final top = (i ~/ _columns) * _rowExtent;
241	    final bottom = top + _rowExtent;
242	    final target = top < pos.pixels
243	        ? top
244	        : bottom > pos.pixels + pos.viewportDimension
245	        ? bottom - pos.viewportDimension
246	        : null;
247	    if (target != null) {
248	      _scroll.jumpTo(target.clamp(pos.minScrollExtent, pos.maxScrollExtent));
249	    }
250	  }
251	
252	  void _close() => unawaited(Navigator.of(context).maybePop());
253	
254	  /// `/` search, `Esc` close; arrows and `Enter` only while the grid itself has focus, so a focused
255	  /// button or the search field keeps its own keys.
256	  KeyEventResult _onKey(FocusNode node, KeyEvent event) {
257	    if (event is! KeyDownEvent && event is! KeyRepeatEvent) {
258	      return KeyEventResult.ignored;
259	    }
260	    final key = event.logicalKey;
261	    if (key == LogicalKeyboardKey.escape) {
262	      _close();
263	      return KeyEventResult.handled;
264	    }
265	    final typing = _search.hasFocus;
266	    if (key == LogicalKeyboardKey.slash && !typing) {
267	      _search.requestFocus();
268	      return KeyEventResult.handled;
269	    }
270	    final items = _items ?? const <MediaItem>[];
271	    if (items.isEmpty) return KeyEventResult.ignored;
272	    if (typing && key == LogicalKeyboardKey.arrowDown) {
273	      _keys.requestFocus();
274	      _select(_selected ?? 0);
275	      return KeyEventResult.handled;
276	    }
277	    if (!_keys.hasPrimaryFocus) return KeyEventResult.ignored;
278	    final step = key == LogicalKeyboardKey.arrowLeft
279	        ? -1
280	        : key == LogicalKeyboardKey.arrowRight
281	        ? 1
282	        : key == LogicalKeyboardKey.arrowUp
283	        ? -_columns
284	        : key == LogicalKeyboardKey.arrowDown
285	        ? _columns
286	        : 0;
287	    final current = _selected;
288	    if (step != 0) {
289	      _select(
290	        current == null ? 0 : (current + step).clamp(0, items.length - 1),
291	      );
292	      return KeyEventResult.handled;
293	    }
294	    if ((key == LogicalKeyboardKey.enter ||
295	            key == LogicalKeyboardKey.numpadEnter) &&
296	        current != null) {
297	      if (_busy == null) unawaited(_primary(items[current]));
298	      return KeyEventResult.handled;
299	    }
300	    return KeyEventResult.ignored;
301	  }
302	
303	  @override
304	  Widget build(BuildContext context) => WtScaffold(
305	    child: Focus(
306	      focusNode: _keys,
307	      autofocus: true,
308	      onKeyEvent: _onKey,
309	      child: WtBackdrop(
310	        child: Padding(
311	          padding: const EdgeInsets.all(WtSpace.window),
312	          child: LayoutBuilder(
313	            builder: (context, box) {
314	              final narrow = box.maxWidth < 1000;
315	              return Column(
316	                crossAxisAlignment: CrossAxisAlignment.stretch,
317	                children: [
318	                  _header(narrow),
319	                  const SizedBox(height: 20),
320	                  _tabs(narrow),
321	                  const SizedBox(height: 18),
322	                  Expanded(child: _body()),
323	                ],
324	              );
325	            },
326	          ),
327	        ),
328	      ),
329	    ),
330	  );
331	
332	  Widget _header(bool narrow) {
333	    final title = Column(
334	      crossAxisAlignment: CrossAxisAlignment.start,
335	      mainAxisSize: MainAxisSize.min,
336	      children: [
337	        Text(
338	          _queueMode ? 'Add to queue' : 'Library',
339	          style: Theme.of(context).textTheme.headlineMedium,
340	        ),
341	        const SizedBox(height: 4),
342	        Text(
343	          _queueMode
344	              ? 'Queue as many as you like. Each one goes to the end.'
345	              : 'Pick what you will play. Everyone opens their own copy.',
346	          maxLines: 2,
347	          overflow: TextOverflow.ellipsis,
348	          style: _muted,
349	        ),
350	      ],
351	    );
352	    final search = WtField(
353	      controller: _query,
354	      focusNode: _search,
355	      hint: 'Search',
356	      icon: Icons.search_rounded,
357	      height: 52,
358	      onChanged: (_) => _reload(fresh: false),
359	      onSubmitted: (_) {
360	        if (_items?.isNotEmpty ?? false) {
361	          _keys.requestFocus();
362	          _select(_selected ?? 0);
363	        }
364	      },
365	      trailing: const _KeyHint('/'),
366	    );
367	    final end = [
368	      if (_queueMode && _queued.isNotEmpty) ...[
369	        WtPill(
370	          label: '${_queued.length} queued',
371	          tone: WtTone.live,
372	          icon: Icons.check_rounded,
373	          fontSize: 13,
374	        ),
375	        const SizedBox(width: 12),
376	      ],
377	      if (_queueMode)
378	        WtButton(label: 'Done', onPressed: _close)
379	      else
380	        WtIconButton(
381	          icon: Icons.close_rounded,
382	          tooltip: 'Close (Esc)',
383	          onPressed: _close,
384	        ),
385	    ];
386	    if (narrow) {
387	      return Column(
388	        crossAxisAlignment: CrossAxisAlignment.stretch,
389	        children: [
390	          Row(
391	            children: [
392	              Expanded(child: title),
393	              const SizedBox(width: 16),
394	              ...end,
395	            ],
396	          ),
397	          const SizedBox(height: 16),
398	          search,
399	        ],
400	      );
401	    }
402	    return Row(
403	      children: [
404	        Expanded(child: title),
405	        const SizedBox(width: 24),
406	        SizedBox(width: 380, child: search),
407	        const SizedBox(width: 16),
408	        ...end,
409	      ],
410	    );
411	  }
412	
413	  Widget _tabs(bool narrow) {
414	    final source = _source;
415	    final tabs = [
416	      for (final (i, s) in widget.sources.indexed) ...[
417	        if (i > 0) const SizedBox(width: 8),
418	        _SourceTab(
419	          source: s,
420	          selected: i == _tab,
421	          onTap: s.available ? () => _pickTab(i) : null,
422	        ),
423	      ],
424	    ];
425	    final extras = [
426	      if (source.account case final account?)
427	        Flexible(
428	          child: Text(
429	            account,
430	            maxLines: 1,
431	            overflow: TextOverflow.ellipsis,
432	            style: _muted.copyWith(fontSize: 13),
433	          ),
434	        ),
435	      if (!_emptyLibrary)
436	        for (final action in source.actions)
437	          WtTextButton(
438	            label: _busy == action.label ? 'Checking…' : action.label,
439	            icon: action.icon,
440	            compact: true,
441	            onPressed: _busy == null ? () => _run(action) : null,
442	          ),
443	    ];
444	    if (!narrow) return Row(children: [...tabs, const Spacer(), ...extras]);
445	    return Column(
446	      crossAxisAlignment: CrossAxisAlignment.start,
447	      children: [
448	        SingleChildScrollView(
449	          scrollDirection: Axis.horizontal,
450	          child: Row(children: tabs),
451	        ),
452	        if (extras.isNotEmpty) ...[
453	          const SizedBox(height: 10),
454	          Row(children: extras),
455	        ],
456	      ],
457	    );
458	  }
459	
460	  Widget _body() {
461	    final source = _source;
462	    final items = _items;
463	    final error = _error;
464	    if (!source.ready) {
465	      return _EmptyState(
466	        icon: Icons.link_rounded,
467	        title: 'Not signed in to ${source.label}',
468	        body: error == null
469	            ? 'Sign in to browse it here. The room only ever shares which item, '
470	                  'never your account.'
471	            : '$error',
472	        actions: [
473	          WtButton(
474	            label: _busy == _connecting
475	                ? 'Connecting…'
476	                : 'Connect ${source.label}',
477	            icon: Icons.login_rounded,
478	            onPressed: _busy == null ? _connect : null,
479	          ),
480	        ],
481	      );
482	    }
483	    if (items == null) return _Loading(label: 'Loading ${source.label}…');
484	    if (error != null) {
485	      return _EmptyState(
486	        icon: Icons.cloud_off_outlined,
487	        title: "Couldn't load ${source.label}",
488	        body: '$error',
489	        actions: [
490	          WtButton(
491	            label: 'Try again',
492	            style: WtButtonStyle.ghost,
493	            onPressed: _reload,
494	          ),
495	        ],
496	      );
497	    }
498	    final query = _query.text.trim();
499	    if (items.isEmpty && query.isNotEmpty) {
500	      return _EmptyState(
501	        icon: Icons.search_off_rounded,
502	        title: 'No matches for “$query”',
503	        body: 'Try another word, or clear the search.',
504	        actions: [
505	          WtButton(
506	            label: 'Clear search',
507	            style: WtButtonStyle.ghost,
508	            onPressed: () {
509	              _query.clear();
510	              _reload(fresh: false);
511	            },
512	          ),
513	        ],
514	      );
515	    }
516	    if (_emptyLibrary) {
517	      return _EmptyState(
518	        icon: Icons.video_library_outlined,
519	        title: 'Nothing in this library yet',
520	        body: source.emptyHint,
521	        actions: [
522	          for (final action in source.actions)
523	            WtButton(
524	              label: _busy == action.label ? 'Checking…' : action.label,
525	              icon: action.icon,
526	              onPressed: _busy == null ? () => _run(action) : null,
527	            ),
528	        ],
529	      );
530	    }
531	    return _grid(items);
532	  }
533	
534	  Widget _grid(List<MediaItem> items) => LayoutBuilder(
535	    builder: (context, box) {
536	      const gap = 18.0;
537	      const minTile = 168.0;
538	      const text = 58.0;
539	      // Room for the focus ring, which sits 5px outside the art.
540	      const edge = 6.0;
541	      final width = box.maxWidth - 2 * edge;
542	      final columns = ((width + gap) / (minTile + gap)).floor().clamp(2, 8);
543	      final tile = (width - gap * (columns - 1)) / columns;
544	      final extent = tile * 1.5 + text;
545	      _columns = columns;
546	      _rowExtent = extent + gap;
547	      return GridView.builder(
548	        controller: _scroll,
549	        padding: const EdgeInsets.all(edge),
550	        gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
551	          crossAxisCount: columns,
552	          mainAxisSpacing: gap,
553	          crossAxisSpacing: gap,
554	          mainAxisExtent: extent,
555	        ),
556	        itemCount: items.length,
557	        itemBuilder: (context, i) {
558	          final item = items[i];
559	          return _MediaCard(
560	            item: item,
561	            poster: widget.poster,
562	            selected: i == _selected,
563	            queued: _queued.contains(item.ref),
564	            busy: _busy == item.ref,
565	            queueMode: _queueMode,
566	            onSelect: () {
567	              _keys.requestFocus();
568	              setState(() => _selected = i);
569	            },
570	            onPlay: _queueMode || _busy != null ? null : () => _play(item),
571	            onQueue: widget.onQueue == null ? null : () => _queue(item),
572	          );
573	        },
574	      );
575	    },
576	  );
577	}
