const String defaultServerUrl = 'https://watch.141.253.97.15.sslip.io';

const Key homeCardKey = ValueKey('home-card');

String? validateServerUrl(String? value) {
  final uri = Uri.tryParse((value ?? '').trim());
  return uri != null &&
          (uri.scheme == 'http' || uri.scheme == 'https') &&
          uri.host.isNotEmpty
      ? null
      : 'Enter an http:// or https:// server URL';
}

/// Where the pasted invite stands after parsing and `GET /rooms/{id}`.
enum InviteState {
  empty,
  malformed,
  checking,
  found,
  unchecked,
  expired,
  ended,
}

class HomeScreen extends StatefulWidget {
  const HomeScreen({
    super.key,
    this.api = const HttpRoomApi(),
    this.pickCopy = pickLocalCopy,
    this.jellyfin = const HttpJellyfinApi(),
    this.initialInvite,
    this.forwardedInvites,
  });
  final RoomApi api;
  final PickCopy pickCopy;
  final JellyfinApi jellyfin;

  /// Invite URL the app was launched with, if any.
  final String? initialInvite;

  /// Invites that arrived from a second launch while this window was already open.
  final Stream<String>? forwardedInvites;

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  final _invite = TextEditingController();
  String _server = defaultServerUrl;
  String _name = Platform.localHostname == 'localhost'
      ? 'You'
      : Platform.localHostname;
  int? _rtt;
  bool _offline = false;
  InviteLink? _link;
  InviteState _state = InviteState.empty;
  RoomInfo? _info;
  int _lookupSeq = 0;
  LocalCopy? _copy;
  bool _creating = false;
  String? _createError;

  late final _local = LocalMediaSource(pickFile: widget.pickCopy);

  /// Restored from the saved config at startup; the library's `Connect Jellyfin` signs in.
  late final _jellyfin = JellyfinMediaSource(
    api: widget.jellyfin,
    signIn: (previous) =>
        showJellyfinSignIn(context, api: widget.jellyfin, previous: previous),
  );

  /// Shared with the room, so a sign-in or a file opened here is still there after joining.
  late final _sources = mediaSources(local: _local, jellyfin: _jellyfin);

  Uri get _serverUri => Uri.parse(_server);

  @override
  void initState() {
    super.initState();
    unawaited(_ping());
    unawaited(_jellyfin.restore());
    final invite = widget.initialInvite;
    if (invite != null && invite.isNotEmpty) {
      _invite.text = invite;
      _onInvite(invite);
    }
    _forwarded = widget.forwardedInvites?.listen(_takeForwarded);
  }

  StreamSubscription<String>? _forwarded;

  /// A later launch handed us an invite: show it without losing the room we are already in.
  void _takeForwarded(String text) {
    final link = parseInviteLink(text);
    if (link == null || !mounted) return;
    _invite.text = text;
    _onInvite(text);
  }

  @override
  void dispose() {
    unawaited(_forwarded?.cancel());
    _invite.dispose();
    super.dispose();
  }

  Future<void> _ping() async {
    setState(() {
      _rtt = null;
      _offline = false;
    });
    final server = _server;
    try {
      final rtt = await widget.api.ping(_serverUri);
      if (mounted && server == _server) setState(() => _rtt = rtt);
    } on Object {
      if (mounted && server == _server) setState(() => _offline = true);
    }
  }

  void _onInvite(String text) {
    final link = parseInviteLink(text);
    final seq = ++_lookupSeq;
    setState(() {
      _link = link;
      _info = null;
      _state = text.trim().isEmpty
          ? InviteState.empty
          : link == null
          ? InviteState.malformed
          : InviteState.checking;
    });
    if (link != null) unawaited(_lookup(link, seq));
  }

  Future<void> _lookup(InviteLink link, int seq) async {
    InviteState state;
    RoomInfo? info;
    try {
      info = await widget.api.lookup(_serverUri, link.room);
      final exp = tokenExpiryMs(link.token);
      state = info == null
          ? InviteState.ended
          : exp != null && exp <= DateTime.now().millisecondsSinceEpoch
          ? InviteState.expired
          : InviteState.found;
    } on Object {
      // Fail open: the code is still shown and joining stays possible.
      state = InviteState.unchecked;
    }
    if (!mounted || seq != _lookupSeq) return;
    setState(() {
      _state = state;
      _info = info;
    });
  }

  Future<void> _paste() async {
    final data = await Clipboard.getData(Clipboard.kTextPlain);
    final text = data?.text?.trim();
    if (text == null || text.isEmpty || !mounted) return;
    _invite.text = text;
    _onInvite(text);
  }

  /// The library; what is played there becomes the copy to join with. [initial] opens on that
  /// source's tab.
  Future<void> _pickMedia({MediaSourceKind? initial}) async {
    final copy = await showMediaLibrary(
      context,
      sources: _sources,
      initial: initial,
    );
    if (copy != null && mounted) setState(() => _copy = copy);
  }

  bool get _linkUsable =>
      _link != null &&
      (_state == InviteState.found ||
          _state == InviteState.unchecked ||
          _state == InviteState.checking);

  bool get _canJoin =>
      _copy != null &&
      _link != null &&
      (_state == InviteState.found || _state == InviteState.unchecked);

  void _join() {
    if (!_canJoin) return;
    _enter(_link!, copy: _copy);
  }

  void _enter(InviteLink link, {String? hostId, LocalCopy? copy}) {
    Navigator.of(context).push(
      wtRoute(
        RoomScreen(
          server: _serverUri,
          room: link.room,
          token: link.token,
          name: _name,
          clientId: hostId,
          initialCopy: copy,
          sources: _sources,
        ),
      ),
    );
  }

  Future<void> _createRoom() async {
    setState(() {
      _creating = true;
      _createError = null;
    });
    try {
      final created = await widget.api.create(_serverUri);
      if (!mounted) return;
      setState(() => _creating = false);
      final enter = await showRoomReady(
        context,
        server: _serverUri,
        created: created,
        name: _name,
        copy: _copy,
        api: widget.api,
        pickCopy: widget.pickCopy,
        onCopy: (copy) {
          _local.remember(copy);
          setState(() => _copy = copy);
        },
      );
      if (enter == true && mounted) {
        _enter(
          (room: created.room, token: created.token),
          hostId: created.hostId,
          copy: _copy,
        );
      }
    } on Object catch (e) {
      if (mounted) setState(() => _createError = '$e');
    } finally {
      if (mounted && _creating) setState(() => _creating = false);
    }
  }

  void _askForNewLink() {
    final host = _info?.hostName;
    final code = _link?.room ?? '';
    Clipboard.setData(
      ClipboardData(
        text:
            'My watch·together invite for room $code expired — '
            'could you send a fresh link?',
      ),
    );
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          host == null
              ? 'Message copied — paste it to whoever invited you'
              : 'Message copied — paste it to $host',
        ),
      ),
    );
  }

  Future<void> _changeServer() async {
    final value = await promptText(
      context,
      title: 'Server',
      initial: _server,
      hint: 'https://…',
      icon: Icons.dns_outlined,
      validate: validateServerUrl,
    );
    if (value == null || !mounted) return;
    setState(() => _server = value);
    unawaited(_ping());
    if (_link != null) _onInvite(_invite.text);
  }

  Future<void> _changeName() async {
    final value = await promptText(
      context,
      title: 'Your name',
      initial: _name,
      hint: 'What friends call you',
      icon: Icons.person_outline,
      validate: (v) =>
          (v ?? '').trim().isEmpty ? 'Enter a name others will see' : null,
    );
    if (value != null && mounted) setState(() => _name = value);
  }

  int get _nextStep => !_linkUsable
      ? 0
      : _copy == null
      ? 1
      : 2;

  @override
  Widget build(BuildContext context) => WtScaffold(
    child: Focus(
      autofocus: true,
      onKeyEvent: _onKey,
      child: WtBackdrop(
        child: LayoutBuilder(
          builder: (context, box) {
            final inner = box.maxWidth - 2 * WtSpace.window;
            final gap = ((inner - 320 - 504) / 3).clamp(48.0, 144.0);
            final brandHeight = (box.maxHeight - 2 * WtSpace.window).clamp(
              0.0,
              640.0,
            );
            final compact = box.maxWidth < wtCompactWidth;
            return SingleChildScrollView(
              padding: const EdgeInsets.all(WtSpace.window),
              child: ConstrainedBox(
                constraints: BoxConstraints(
                  minHeight: box.maxHeight - 2 * WtSpace.window,
                ),
                child: Center(
                  child: compact
                      ? Column(
                          mainAxisSize: MainAxisSize.min,
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          children: [
                            _Brand(
                              next: _nextStep,
                              status: _statusRow(),
                              onLibrary: _pickMedia,
                              compact: true,
                            ),
                            const SizedBox(height: 32),
                            _card(),
                          ],
                        )
                      : Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            SizedBox(
                              width: 320,
                              height: brandHeight,
                              child: _Brand(
                                next: _nextStep,
                                status: _statusRow(),
                                onLibrary: _pickMedia,
                              ),
                            ),
                            SizedBox(width: gap),
                            SizedBox(width: 504, child: _card()),
                          ],
                        ),
                ),
              ),
            );
          },
        ),
      ),
    ),
  );

  /// Ctrl+V anywhere on Home pastes the invite, unless a text field already has focus.
  KeyEventResult _onKey(FocusNode node, KeyEvent event) {
    if (event is! KeyDownEvent ||
        event.logicalKey != LogicalKeyboardKey.keyV ||
        !HardwareKeyboard.instance.isControlPressed) {
      return KeyEventResult.ignored;
    }
    final focused = FocusManager.instance.primaryFocus?.context;
    if (focused?.findAncestorWidgetOfExactType<EditableText>() != null) {
      return KeyEventResult.ignored;
    }
    unawaited(_paste());
    return KeyEventResult.handled;
  }

