import 'package:watch_together/widgets/button.dart';
import 'package:watch_together/widgets/chrome.dart';

import 'support.dart';

const RoomInfo liveRoom = RoomInfo(
  roomId: roomCode,
  hostName: 'Mika',
  memberCount: 2,
  memberNames: ['Mika', 'Jo'],
  itemRef: hostRef,
  positionMs: 724000,
  paused: false,
);

void main() {
  final clipboard = FakeClipboard();
