import 'support.dart';

const List<RoomPerson> crowd = [
  RoomPerson(id: 'mika', name: 'Mika', host: true),
  RoomPerson(
    id: 'me',
    name: 'Sam',
    you: true,
    state: PersonState.drifting,
    driftMs: 2300,
  ),
  RoomPerson(id: 'jo', name: 'Jo', state: PersonState.noFile),
  RoomPerson(id: 'al', name: 'Al', state: PersonState.buffering),
  RoomPerson(id: 'ri', name: 'Ri', state: PersonState.reconnecting),
];

RoomViewData video({
  bool connected = true,
  bool playing = true,
  List<RoomPerson> people = crowd,
  PauseNotice? pause,
  String? waitingFor,
  bool fullscreen = false,
  double aspect = 16 / 9,
}) => RoomViewData(
  room: roomCode,
  title: "Mika's room",
  invite: 'https://example.com/join/abc.sig',
  connected: connected,
  people: people,
  nowPlaying: (
    title: 'movie-night_1080p.mkv',
    detail: '1:52:10',
    source: MediaSource.local,
  ),
  upNext: const [
    (
      title: 'episode-02_1080p.mkv',
      detail: '24:10',
      source: MediaSource.jellyfin,
    ),
  ],
  stage: StageMode.video,
  fileName: 'movie-night_1080p.mkv',
  positionMs: 724000,
  durationMs: 6730000,
  bufferedMs: 900000,
  playing: playing,
  pause: pause,
  waitingFor: waitingFor,
  fullscreen: fullscreen,
  aspect: aspect,
);

const RoomViewData empty = RoomViewData(
  room: roomCode,
  people: [
    RoomPerson(
      id: 'me',
      name: 'Sam',
      you: true,
      host: true,
      state: PersonState.noFile,
    ),
  ],
);

void main() {
  setUp(FakeClipboard().install);

  Future<void> pumpRoom(
    WidgetTester tester,
    RoomViewData data, {
    VoidCallback? onPlay,
    VoidCallback? onPause,
    ValueChanged<int>? onSeekBy,
    ValueChanged<int>? onSeekTo,
    VoidCallback? onFullscreen,
    VoidCallback? onToggleMute,
    VoidCallback? onOpenJellyfin,
    VoidCallback? onAddToQueue,
    VoidCallback? onQueueJellyfin,
  }) async {
    await tester.pumpWidget(
      MaterialApp(
        theme: wtTheme(),
        home: WtScaffold(
          child: RoomView(
            data: data,
            video: const ColoredBox(color: Colors.black),
            onBack: () {},
            onOpenFile: () {},
            onOpenJellyfin: onOpenJellyfin,
            onPlay: onPlay ?? () {},
            onPause: onPause ?? () {},
            onSeekBy: onSeekBy ?? (_) {},
            onSeekTo: onSeekTo ?? (_) {},
            onToggleMute: onToggleMute ?? () {},
            onFullscreen: onFullscreen ?? () {},
            onSettings: () {},
            onAddToQueue: onAddToQueue ?? () {},
            onQueueJellyfin: onQueueJellyfin,
          ),
        ),
      ),
    );
    await tester.pump();
  }

  /// Dock tooltips carry their disabled reason (`Back 10 seconds · open a file first`), so match on
  /// the prefix rather than the whole string.
  WtTap tapFor(WidgetTester tester, String tooltip) => tester.widget<WtTap>(
    find
        .ancestor(
          of: find.byWidgetPredicate(
            (w) => w is Tooltip && (w.message ?? '').startsWith(tooltip),
          ),
          matching: find.byType(WtTap),

