      await tester.tap(find.text('Show controls'));
      await tester.pump();
      await idle(tester);
      await idle(tester);
      expect(dock(tester), 1);
      expect(noCursor, findsNothing);

      await tester.tap(find.text('Show controls'));
      await tester.pump();
      expect(dock(tester), 1);
      await idle(tester);
      expect(dock(tester), 0);
    });

    testWidgets(
      'click the picture to play or pause, double-click to leave; the dock keeps its clicks',
