final Uri jellyServer = Uri.parse('https://jelly.example');

final RoomInfo jellyRoom = RoomInfo(
  roomId: roomCode,
  hostName: 'Mika',
  memberCount: 2,
  memberNames: const ['Mika', 'Jo'],
  itemRef: jellyfinRef(jellyServer, jellyItemId),
  positionMs: 4000,
  paused: false,
);

void main() {
  Future<void> pumpHome(WidgetTester tester, FakeJellyfinApi jellyfin) async {
    useWindow(tester, desktopSizes.first);
    await tester.pumpWidget(
      MaterialApp(
        theme: wtTheme(),
        home: HomeScreen(
          api: FakeRoomApi(info: jellyRoom),
          pickCopy: () async => null,
          jellyfin: jellyfin,
        ),
      ),
    );
    await tester.pump();
    await tester.enterText(
      find.byType(TextField),
      'https://example.com/join/${token(roomCode, exp: inTenMinutes())}',
    );
    await tester.pump();
    await tester.pump();
  }

  Future<void> settle(WidgetTester tester) async {
    for (var i = 0; i < 4; i++) {
      await tester.pump();
    }
    await tester.pump(const Duration(milliseconds: 400));
  }

  /// `Pick media`, then the library's Jellyfin tab.
  Future<void> openJellyfinTab(WidgetTester tester) async {
    await tester.tap(find.text('Pick media'));
