  group('queue Add', () {
    testWidgets('Add opens the queue route', (tester) async {
      useWindow(tester, desktopSizes.first);
      var adds = 0;
      await pumpRoom(tester, video(), onAddToQueue: () => adds++);
      await tester.tap(find.text('Add'));
      await tester.pump();
      expect(adds, 1);
    });

    test('a queued library item is remembered and sent under its own ref', () {
      final known = <String, ({String name, int? durationMs})>{};
      final sent = <(String, Map<String, Object?>)>[];
      void send(String op, Map<String, Object?> args) => sent.add((op, args));
      const jellyRef = 'jellyfin:jelly.example/$jellyItemId';
      queueItem(
        const MediaItem(
          ref: jellyRef,
          title: 'sample-room',
          kind: MediaKind.video,
          source: MediaSourceKind.jellyfin,
          duration: Duration(seconds: 20),
        ),
        known: known,
        send: send,
      );
      queueItem(
        LocalMediaSource.itemFor(hostCopy),
        known: known,
        send: send,
      );
      expect(sent, [
        ('queue_add', {'item_ref': jellyRef}),
        ('queue_add', {'item_ref': hostRef}),
      ]);
      expect(known[jellyRef], (name: 'sample-room', durationMs: 20000));
      expect(known[hostRef], (
        name: 'movie-night_1080p.mkv',
        durationMs: hostCopy.duration!.inMilliseconds,
      ));
    });

    testWidgets('Add is disabled while disconnected', (tester) async {
      useWindow(tester, desktopSizes.first);
      var adds = 0;
      await pumpRoom(
        tester,
        video(connected: false),
        onAddToQueue: () => adds++,
      );
      await tester.tap(find.text('Add'), warnIfMissed: false);
      await tester.pump();
      expect(adds, 0);
    });

    testWidgets('queue rows carry the Jellyfin or Local file chip', (
      tester,
    ) async {
      useWindow(tester, desktopSizes.first);
      await pumpRoom(tester, video());
      // video(): a local file now playing, a Jellyfin item up next; the dock shows no chip.
      expect(find.text('Local file'), findsOneWidget);
      expect(find.text('Jellyfin'), findsOneWidget);
      expect(tester.takeException(), isNull);
    });
  });

  testWidgets('empty room: open-file stage, dimmed dock, nothing queued', (
    tester,
  ) async {
    useWindow(tester, desktopSizes.first);
    await pumpRoom(tester, empty);
    expect(find.text('Open a file to watch together'), findsOneWidget);
    expect(find.text('Open file'), findsOneWidget);
    expect(find.text('Nothing queued'), findsOneWidget);
    expect(tapFor(tester, 'Play (Space)').onTap, isNull);
    expect(tapFor(tester, 'Back 10 seconds').onTap, isNull);
    expect(tapFor(tester, 'Fullscreen (F)').onTap, isNull);
  });

  testWidgets('waiting stage says the room has another file', (tester) async {
    useWindow(tester, desktopSizes.first);
    await pumpRoom(
      tester,
      const RoomViewData(room: roomCode, stage: StageMode.waiting),
    );
    expect(find.text("Open the room's file to join"), findsOneWidget);
    expect(find.text('Open that file…'), findsOneWidget);
  });

  testWidgets('a paused room names who it waits for', (tester) async {
    useWindow(tester, desktopSizes.first);
    await pumpRoom(
      tester,
      video(
        playing: false,
        waitingFor: 'Mika',
        pause: const PauseNotice(serial: 1, positionMs: 724000, by: 'Mika'),
      ),
